// 版本号只在这里写一次，设置页和关于页都读它
const APP_VERSION = 'v7.21';
let groupMap = new Map();
const WEEK = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];

function isoOf(d) {
  const p = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}
function parseISO(s) {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, m - 1, d);
}
function todayISO() { return isoOf(new Date()); }
function addDays(s, n) {
  const d = parseISO(s);
  d.setDate(d.getDate() + n);
  return isoOf(d);
}
function esc(s) {
  return String(s).replace(/[&<>"']/g, c => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function round(n) { return Math.round(Number(n) || 0); }

let toastTimer = null;

/* 提醒记录弹层的界面开关
   ── 现在的状态：只有顶部小横杠（66px），没有 ×，也没有标题
   ── 用户要求「恢复叉叉」时，按 v4.41 的样子恢复：
        closeX: true, showTitle: true, titleCenter: false
      这样标题会回到左上、和 ×（距顶 0.52 个圆角半径）同一条中心线、16px。
      注意：横杠宽度（66px）和卡片玻璃质感【不要】跟着回退，保持现状。 */
const NLOG_UI = { closeX: false, grab: true, titleCenter: false, showTitle: false };
let bodyTrendPage = 0;     // 体重趋势第几页（0 = 最新的 7 次记录）
let trSelDate = null;      // 趋势页体重图上点选的日期
let bodySelDate = null;    // 图上点选的那一天（不点 = 最近一次）
const WATCH_NAME = "Karen's Apple Watch";
const SCALE_NAME = "米家体脂秤";

// 统一提示：✅ 已更新：<更新了什么> <日期> · <哪台设备>
function updToast(what, date, device, ms = 2600) {
  const d = date ? ' ' + String(date).slice(5) : '';
  const main = `✅ 已更新：${what}${d}${device ? ' · ' + device : ''}`;
  // 放不下时：设备名整体换到下一行，不在词中间断开
  const alt = `✅ 已更新：${what}${d}${device ? '\n' + device : ''}`;
  toast(main, ms, alt);
}

function toast(msg, ms = 2200, alt) {
  const t = $('#toast');
  t.textContent = msg;
  t.classList.add('on');
  // 精确判断这行字会不会折行：量一遍不换行时有多宽，超过可用宽度就把「·」去掉
  if (alt) {
    try {
      const probe = document.createElement('span');
      probe.textContent = msg;
      probe.style.cssText = 'position:absolute;left:-9999px;top:0;visibility:hidden;white-space:nowrap;';
      probe.style.font = getComputedStyle(t).font;
      t.appendChild(probe);
      const full = probe.getBoundingClientRect().width;
      probe.remove();
      const cs = getComputedStyle(t);
      const avail = t.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0);
      if (full > avail + 1) t.textContent = alt;
    } catch (e) {}
  }
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove('on'), ms);
}

/* ---------------- 状态 ---------------- */
const SYNC_SHORTCUT = '热量采集';
let pendingSync = false;

const S = {
  date: todayISO(),
  today: todayISO(),
  day: null,
  foods: [],
  view: 'today',
  trendDays: 30,
  trend: null,
  addMode: 'photo',
  photoData: null,
  photoAt: null,
  photoURL: null,
  batchName: null,
  photo2Data: null,
  photo2URL: null,
  openGroups: new Set(),
  items: [],
  meal: 'lunch',
};

function defaultMeal() {
  const h = new Date().getHours();
  if (h < 10) return 'breakfast';
  if (h < 15) return 'lunch';
  if (h < 21) return 'dinner';
  return 'snack';
}

/* ---------------- 加载 ---------------- */
async function loadDay() {
  try {
    const d = await api('/api/bootstrap?date=' + S.date);
    S.day = d;
    S.foods = d.foods || [];
    renderToday();
    window.__booted = true;
    if (window.__bootT) clearTimeout(window.__bootT);
  } catch (e) {
    // 读失败时别把界面留在"全是破折号"：先自己再试一次，仍失败就给一条可点重试的提示
    console.warn('loadDay', e);
    if (!window.__dayRetried) {
      window.__dayRetried = true;
      setTimeout(loadDay, 800);
      return;
    }
    toast('加载失败：' + e.message, 4000);
    if (window.__showBootRetry) window.__showBootRetry('数据没读出来');
  }
}

/* ---------------- 渲染：今日 ---------------- */
function renderToday() {
  const d = S.day;
  if (!d) return;
  // 用实时时钟兜底：如果看的是"今天"但日期已经翻篇，直接切过去
  const nowDay = todayISO();
  if (S.date === S.today && nowDay !== S.today) {
    S.today = nowDay;
    S.date = nowDay;
    loadDay();
    return;
  }

  const dt = parseISO(d.date);
  $('#dateLabel').textContent = `${dt.getMonth() + 1}月${dt.getDate()}日`;
  const isToday = d.date === S.today;
  // 日期下面那行：直接写清"这份数据是几点同步的"，不用再往下找
  const watchAt = (d.watch && d.watch.source === 'cloud' && d.watch.cloudAt) ? String(d.watch.cloudAt).slice(11, 16) : '';
  $('#dateSub').textContent = isToday
    ? (watchAt ? `今天 · ${watchAt} 更新` : '今天 · 实时')
    : (watchAt ? `${WEEK[dt.getDay()]} · ${watchAt}` : WEEK[dt.getDay()]);
  $('#nextDay').disabled = isToday;
  $('#nextDay').style.opacity = isToday ? 0.45 : 1;

  const t = d.targets;
  const intake = d.intake;
  const expFull = d.expenditure;          // 全天预估/实际
  const balFull = d.balance;

  // 今天只算“到现在为止”的消耗，历史日期用全天值
  let dayFrac = 1;
  if (d.date === S.today) {
    const start = new Date(d.date + 'T00:00:00').getTime();
    dayFrac = Math.min(1, Math.max(0, (Date.now() - start) / 86400000));
  }
  // 今天：基础代谢按时间折算，手表的活动能量是“到现在为止”的，全额计入
  const det = d.expenditure_detail || {};
  let exp;
  if (d.date === S.today) {
    if (det.active && det.resting) exp = Math.round(det.resting * dayFrac) + det.active;
    else if (det.total) exp = Math.round(det.total * dayFrac);
    else exp = Math.round(expFull * dayFrac);
  } else {
    exp = expFull;
  }
  const bal = d.date === S.today ? exp - intake : balFull;
  const left = t.kcal_budget - intake;

  // 首次使用提示
  const sb = $('#setupBanner');
  if (d.needs_setup) {
    sb.innerHTML = `<button class="setup-tip" id="goSetup">
      <span>先填身高体重，消耗才算得准</span><b>去填 →</b></button>`;
    $('#goSetup').onclick = () => switchView('me');
  } else {
    sb.innerHTML = '';
  }

  // 主环
  const pct = t.kcal_budget > 0 ? intake / t.kcal_budget : 0;
  const ring = $('#ring');
  const C = 527.8;
  const dash = String(C * (1 - Math.min(pct, 1)));
  ring.style.strokeDashoffset = dash;
  const rim = $('#ringRim');
  if (rim) rim.style.strokeDashoffset = dash;      // 边光跟着同一段弧走

  // 颜色语言：绿=还有余量、橙=接近上限、红=已经吃超（盈余）
  // 颜色随进度平滑过渡：绿 → 橙 → 红
  const mix = (a, b, t) => {
    const p = h => [parseInt(h.slice(1,3),16), parseInt(h.slice(3,5),16), parseInt(h.slice(5,7),16)];
    const A = p(a), B = p(b);
    return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0')).join('');
  };
  let c0, c1, c2;
  if (pct <= 0.8) {
    c0 = '#d6ff4b'; c1 = '#57ffc8'; c2 = '#d6ff4b';
  } else if (pct <= 1) {
    const t = (pct - 0.8) / 0.2;
    c0 = mix('#d6ff4b', '#ffc44b', t);
    c1 = mix('#57ffc8', '#ff9a3d', t);
    c2 = mix('#d6ff4b', '#ff7a3d', t);
  } else {
    // 吃超了：橙 → 正红（以前中间那档是玫红，发粉）
    const t = Math.min(1, (pct - 1) / 0.15);
    c0 = mix('#ffc44b', '#ff6a4a', t);
    c1 = mix('#ff9a3d', '#ff2323', t);
    c2 = mix('#ff7a3d', '#ff3b30', t);
  }
  // 让弧线有一点渐变：起点亮一点、终点暗一点（同一个色系，不换色相）
  const shade = (hex, amt) => {
    const p = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
    const f = v => Math.max(0, Math.min(255, Math.round(amt > 0 ? v + (255 - v) * amt : v * (1 + amt))));
    return '#' + p(hex).map(v => f(v).toString(16).padStart(2, '0')).join('');
  };
  $('#ringS0').setAttribute('stop-color', shade(c0, 0.26));
  $('#ringS1').setAttribute('stop-color', c1);
  $('#ringS2').setAttribute('stop-color', shade(c2, -0.22));


  // 一圈很淡的同色光晕：让环看着像玻璃，不是贴上去的色带
  const rgba = (hex, a) => {
    const p = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
    const [r, g, b] = p(hex);
    return `rgba(${r}, ${g}, ${b}, ${a})`;
  };
  ring.style.filter = `drop-shadow(0 0 7px ${rgba(c1, 0.18)})`;

  const hero = $('#hero');
  hero.classList.remove('surplus', 'over');
  // 圈里的数字跟着圈的中间色走（吃超时就是那档红）
  hero.style.setProperty('--hero-c', c1);

  const goalDef = Math.round(t.deficit);   // 正=缺口，负=盈余
  let sub = goalDef > 0 ? `目标缺口 ${goalDef}` : (goalDef < 0 ? `目标盈余 ${-goalDef}` : '维持体重');
  if (bal < 0) {
    hero.classList.add('surplus');
    $('#heroLbl').textContent = '热量盈余';
    $('#heroNum').textContent = Math.abs(bal);
  } else {
    $('#heroLbl').textContent = '热量缺口';
    $('#heroNum').textContent = bal;
  }
  $('#heroSub').textContent = sub;

  $('#stIntake').innerHTML = intake + ' <small>kcal</small>';
  $('#stExp').innerHTML = exp + ' <small>kcal</small>';
  const leftEl = $('#stLeft');
  const at = (d.watch && d.watch.source === 'cloud' && d.watch.cloudAt) ? String(d.watch.cloudAt).slice(11) : '';
  // 看今天、但数据已经超过 90 分钟没更新 → 标一句「偏旧」，不用等发现数字不对
  let stale = false;
  if (at && isToday) {
    const hm = at.match(/(\d{1,2}):(\d{2})/);
    if (hm) { const t0 = parseISO(d.date); t0.setHours(+hm[1], +hm[2], 0, 0); stale = (Date.now() - t0.getTime()) > 90 * 60000; }
  }
  // 有"数据偏旧"时整行（时间 + 数据偏旧）一起变橙；没有就保持原色
  $('#stExpAt').textContent = at ? (at + (stale ? ' · 数据偏旧' : '')) : '';
  $('#stExpAt').style.color = stale ? 'var(--orange)' : '';
  leftEl.innerHTML = (left >= 0 ? left : left) + ' <small>kcal</small>';
  leftEl.style.color = left < 0 ? 'var(--orange)' : '';

  // 营养素
  const pr = d.protein, cb = d.carb, ft = d.fat;
  $('#pNow').textContent = Math.round(pr);
  $('#pGoal').textContent = t.protein_g;
  $('#cNow').textContent = Math.round(cb);
  $('#cGoal').textContent = t.carb_g;
  $('#fNow').textContent = Math.round(ft);
  $('#fGoal').textContent = t.fat_g;
  const w = (v, g) => Math.min(100, g > 0 ? (v / g) * 100 : 0) + '%';
  $('#pBar').style.width = w(pr, t.protein_g);
  $('#cBar').style.width = w(cb, t.carb_g);
  $('#fBar').style.width = w(ft, t.fat_g);

  renderMeals();
}

/* 营养克数的显示：小于 10 保留一位小数，别把 0.3g 显示成 0 */
function g1(v) {
  const n = Number(v) || 0;
  return n >= 10 ? String(Math.round(n)) : String(Math.round(n * 10) / 10);
}

function renderMeals() {
  const d = S.day;
  const box = $('#meals');
  const shots = d.shots || {};
  const thumbOf = l => (l.batch && shots[l.batch]) ? `<img class="mthumb" src="${shots[l.batch]}" alt="">` : '';
  const itemRow = l => `
      <div class="mitem" data-item="${l.id}">
        ${thumbOf(l)}
        <div class="n">${nameLine(l.name, `data-pen="${l.id}"`)}
          <span class="sub">${l.grams ? g1(l.grams) + 'g' : ''}${
            l.p ? ' · 蛋' + g1(l.p) + '·碳' + g1(l.c) + '·脂' + g1(l.f) : ''}<button class="pen inl" data-nutlog="${l.id}" aria-label="改营养数据">${PEN_ICON}</button></span>
        </div>
        <div class="k">${Math.round(l.kcal)}${l.source === 'photo' || l.source === 'ai' ? ' <span class="ai">AI</span>' : ''}</div>
        <span class="chev">›</span>
        <button class="del" data-del="${l.id}">×</button>
      </div>`;

  // 同一次识别出来的多条，收成一行（例如「沙县小吃」→ 展开是青菜/鸡腿/米饭）
  // 老数据没有 batch 标记，就按「同一餐 + 同一秒」归堆
  const groupsById = new Map();
  const groupRows = items => {
    const groups = [];
    const seen = new Map();
    items.forEach(l => {
      const key = l.batch || ('L' + (l.meal || '') + '|' + (l.ts || ''));
      if (!seen.has(key)) {
        const g = { key, name: l.batchName || '', logs: [] };
        seen.set(key, g);
        groups.push(g);
        groupsById.set(key, g);
      }
      seen.get(key).logs.push(l);
    });
    return groups.map(g => {
      if (g.logs.length < 2) return itemRow(g.logs[0]);
      const open = S.openGroups.has(g.key);
      const kcal = Math.round(g.logs.reduce((a, b) => a + (b.kcal || 0), 0));
      const p = g.logs.reduce((a, b) => a + (b.p || 0), 0);
      const c = g.logs.reduce((a, b) => a + (b.c || 0), 0);
      const f = g.logs.reduce((a, b) => a + (b.f || 0), 0);
      return `
      <div class="mitem ghead" data-group="${esc(g.key)}">
        ${thumbOf(g.logs[0])}
        <div class="n">${nameLine(g.name || '未命名', `data-pen-g="${esc(g.key)}"`)}
          <span class="sub">${g.logs.length} 项 · 蛋${Math.round(p)}·碳${Math.round(c)}·脂${Math.round(f)}</span>
        </div>
        <div class="k">${kcal}</div>
        <span class="chev">›</span>
        <button class="del" data-gdel-g="${esc(g.key)}">×</button>
      </div>`;
    }).join('');
  };

  box.innerHTML = MEALS.map(m => {
    const items = d.logs.filter(l => (l.meal || 'other') === m.k);
    const kcal = items.reduce((a, b) => a + (b.kcal || 0), 0);
    const rows = groupRows(items);
    return `
      <div class="meal ${items.length ? 'has' : ''}">
        <div class="hd">
          <span class="dot"></span>
          <span class="nm">${m.n}</span>
          <span class="kc">${items.length ? Math.round(kcal) + ' 千卡' : ''}</span>
          <button class="add" data-add="${m.k}">＋</button>
        </div>
        ${items.length ? `<div class="items">${rows}</div>`
                       : `<div class="empty">还没记录</div>`}
      </div>`;
  }).join('');

  groupMap = groupsById;
  $$('[data-group]', box).forEach(b => b.onclick = () => openGroup(b.dataset.group));
  $$('[data-item]', box).forEach(b => b.onclick = ev => {
    if (ev.target.closest('[data-del]') || ev.target.closest('[data-pen]') || ev.target.closest('[data-gdel-g]')) return;
    openDetail([d.logs.find(l => String(l.id) === b.dataset.item)].filter(Boolean), false);
  });

  // 名字边上的小铅笔：改这一条的名字（识别错了也能自己改回来）
  $$('[data-nutlog]', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    openNutEditLog(b.dataset.nutlog);
  });
  $$('[data-pen]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation(); ev.preventDefault();
    const l = d.logs.find(x => String(x.id) === b.dataset.pen);
    if (!l) return;
    const name = prompt('这个食物叫什么？', l.name || '');
    if (name === null) return;
    const v = name.trim().slice(0, 20);
    if (!v || v === l.name) return;
    try {
      await api('/api/logs/rename', { ids: [l.id], name: v, item: true });
      await loadDay();
      if (S.view === 'trends') loadTrends();
      toast('已改名：' + v, 1800);
    } catch (e) { toast(e.message); }
  });
  $$('[data-pen-g]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation(); ev.preventDefault();
    const g = groupsById.get(b.dataset.penG);
    if (!g) return;
    const name = prompt('这份叫什么？（比如：沙县小吃）', g.name || '');
    if (name === null) return;
    const v = name.trim().slice(0, 20);
    if (!v || v === g.name) return;
    try {
      await api('/api/logs/rename', { ids: g.logs.map(l => l.id), name: v, item: false });
      await loadDay();
      toast('已改名：' + v, 1800);
    } catch (e) { toast(e.message); }
  });

  // 整组那一行的 × ：删掉这一组的所有条目
  $$('[data-gdel-g]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    const g = groupsById.get(b.dataset.gdelG);
    if (!g) return;
    try {
      for (const l of g.logs) await api('/api/logs/' + l.id, null, 'DELETE');
      await loadDay();
      if (S.view === 'trends') loadTrends();
      toast('已删除这一组', 1600);
    } catch (e) { toast(e.message); }
  });

  $$('[data-del]', box).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    try {
      await api('/api/logs/' + b.dataset.del, null, 'DELETE');
      await loadDay();
      if (S.view === 'trends') loadTrends();
    } catch (e) { toast(e.message); }
  });

  $$('[data-add]', box).forEach(b => b.onclick = () => {
    openAdd(b.dataset.add);
  });
}

/* ---------------- 弹层叠放顺序 ---------------- */
/* 记录卡片 / 营养编辑 / 提醒记录 可能同时开着：谁最后打开谁在最上面，
   所以打开时统一往上抬一层（按打开顺序叠，不写死 z-index） */
let sheetZ = 60;
function raiseSheet(id) {
  const el = typeof id === 'string' ? $(id) : id;
  if (!el) return;
  el.style.zIndex = String(++sheetZ);
}

/* ---------------- 记录弹层 ---------------- */
function openAdd(meal) {
  S.items = [];
  S.meal = meal || defaultMeal();
  S.batchName = null;
  $('#batchName').value = '';
  resetPhotoUI();
  restoreDraft();
  $('#photoHint').value = '';
  $('#resultArea').hidden = true;
  $('#addFoot').hidden = true;
  $('#searchInput').value = '';
  $('#textInput').value = '';
  $('#searchList').innerHTML = '';
  $('#searchList').hidden = false;
  $('#addTabs').hidden = false;
  $('#searchInput').value = '';
  setAddMode('photo');
  renderMealPick();
  renderRecent();

  raiseSheet('#addSheet');                   // 刚打开的弹层放到最上面
  document.body.classList.add('add-open');   // 用和提醒记录一样的浅遮罩，玻璃才透得出来
  initAddTabsLens();
  setTimeout(() => { if (window.__addTabsLens) window.__addTabsLens.sync(); }, 60);
  $('#addMask').classList.add('on');
  $('#addSheet').classList.add('on');
}
function closeAdd() {
  document.body.classList.remove('add-open');
  $('#addMask').classList.remove('on');
  const sh = $('#addSheet');
  // 下滑关闭时脚本写过 transform，这里必须清掉，否则下次打开会停在半路
  sh.classList.remove('dragging');
  sh.style.transform = '';
  sh.style.opacity = '';
  sh.classList.remove('on');
}

/* 记录卡片里那三个选项（拍照/搜索/描述）：和 Dock 一样的玻璃滑块 */
const segLensMem = {};   // 记住每一条滑块最后停在哪，DOM 被重建时能接着滑，不会"跳一下"
function initSegLens(wrap) {
  if (!wrap || wrap.dataset.lens) return;
  wrap.dataset.lens = '1';
  const key = wrap.id || wrap.className || 'seg';
  const lens = document.createElement('span');
  lens.className = 'seg-lens';
  wrap.prepend(lens);

  // 用布局坐标（offset*）而不是 getBoundingClientRect：
  // 卡片弹出时有个 scale(.98) 的过渡，用 rect 量出来的尺寸会小 2%，滑块就会偏小、看着不居中
  const geoOf = el => {
    const w = el.offsetWidth, h = el.offsetHeight;
    if (!w || !h) return null;
    let x = 0, y = 0, n = el;
    while (n && n !== wrap) { x += n.offsetLeft; y += n.offsetTop; n = n.offsetParent; }
    return { x: Math.round(x) + 1, y: Math.round(y) + 1, w: w - 2, h: h - 2 };
  };
  // 尺寸只在第一次（或格子尺寸明显变了）时写一次；平时只改 transform，
  // 这样动画过程中不需要重新排版，iOS 上才不会抖
  let cellW = 0, cellH = 0;
  const apply = (g) => {
    if (Math.abs(g.w - cellW) > 2 || Math.abs(g.h - cellH) > 2) {
      cellW = g.w; cellH = g.h;
      lens.style.width = g.w + 'px';
      lens.style.height = g.h + 'px';
    }
    lens.style.transform = 'translate3d(' + g.x + 'px,' + g.y + 'px,0)';
    lens.classList.add('on');
  };
  // 这条滑块之前停在别处（DOM 刚被重建）→ 先瞬移到老位置，再滑过去
  let primed = false;      // 有没有过一次"不带动画"的落位（防止第一次显示时从左上角滑下来）
  const mem = segLensMem[key];
  if (mem) {
    lens.style.transition = 'none';
    apply(mem);
    void lens.offsetWidth;
    lens.style.transition = '';
    primed = true;         // 已经从老位置接着了，下一次可以正常滑动
  }
  // remember=false 用在"按住"的时候：那只是预览位置，不能当成最终落点记下来，
  // 否则重画时新滑块会直接从按住的位置出现，看不到滑过去的过程
  const place = (el, remember = true) => {
    const g = el && geoOf(el);
    if (!g) return;
    if (remember) segLensMem[key] = g;
    apply(g);
  };
  // instant = 不播动画，直接是实色（用于"你根本没点过它"的场合：切页、重画、首次定位）
  let glassUntil = 0;                  // 正在"玻璃→实色"过渡中，到这个时刻为止
  const settleSeg = (delay, instant) => {
    if (instant) {
      // 注意：这里**绝不能**先 clearTimeout —— 那会把"松手后加 settled"的定时器清掉，
      // 结果就是按完一直停在玻璃状态（v6.74 的 bug 就是这个）
      if (Date.now() < glassUntil) return;                 // 正在淡入 → 让它走完，不插队
      clearTimeout(lens.__settleT);
      lens.classList.remove('fadein', 'fadeout');
      lens.classList.add('settled');                       // 不过渡：直接就是实色
      return;
    }
    clearTimeout(lens.__settleT);
    // 有意的操作：先关掉实色（fadeout 的快节奏），再等 delay 后用 fadein 慢慢亮回来
    lens.classList.remove('settled');
    glassUntil = Date.now() + delay + 2400;
    lens.__settleT = setTimeout(() => {
      lens.classList.add('fadein');
      void lens.offsetWidth;                               // 先让 2.2s 的过渡生效，再改 opacity
      lens.classList.add('settled');
      setTimeout(() => lens.classList.remove('fadein'), 2400);
    }, delay);
  };
  const sync = () => {
    lens.classList.remove('press');
    if (!pressedEl) settleSeg(0, true);   // 切页/重画时直接就是实色，不播"玻璃→实色" 
    const on = wrap.querySelector('button.on');
    const g = on && geoOf(on);
    if (!g) return;
    if (!primed) {
      // 第一次定位（刚刷新完、刚切到这一页）：直接落位，绝不播放入场动画
      lens.style.transition = 'none';
      apply(g);
      void lens.offsetWidth;
      lens.style.transition = '';
      segLensMem[key] = g;
      primed = true;
      lens.classList.add('settled');
      return;
    }
    place(on);
  };
  window.__addTabsLens = { sync };

  // 同一帧内多次触发只做一次，避免连点/重绘把滑块来回拽
  let raf = 0;
  const syncSoon = () => {
    if (raf) return;
    raf = requestAnimationFrame(() => { raf = 0; sync(); });
  };

  let pressedEl = null;
  wrap.addEventListener('pointerdown', ev => {
    const b = ev.target.closest('button');
    if (!b) return;
    pressedEl = b;
    lens.classList.add('fadeout');      // 按住/滑动中是玻璃（0.25 秒，跟手）
    lens.classList.remove('settled', 'fadein');
    setTimeout(() => lens.classList.remove('fadeout'), 320);
    place(b, false);                    // 按下去就直接滑到手指这一格（不记账）
  }, { passive: true });

  // 松手时不要立刻弹回原来的格子 —— 那样会"过去又回来"晃一下。
  // 等点击结果落地（或在 900ms 后确认没生效）才决定要不要回位。
  const settle = () => {
    const el = pressedEl;
    pressedEl = null;
    if (!el) return;          // 没按在这一排上 → 什么都不做（否则点页面任何地方都会闪一下实色）
    settleSeg(260);
    setTimeout(() => {
      if (!wrap.isConnected) return;              // 整块已经被重画，新滑块自己会接上
      const on = wrap.querySelector('button.on');
      if (on && on !== el) sync();                // 按了但没切过去 → 回位
    }, 900);
  };
  window.addEventListener('pointerup', settle, { passive: true });
  window.addEventListener('pointercancel', settle, { passive: true });

  // 只要哪一格变成选中就跟着走（不依赖各页自己的点击处理）
  const mo = new MutationObserver(syncSoon);
  wrap.querySelectorAll('button').forEach(b => mo.observe(b, { attributes: true, attributeFilter: ['class'] }));

  requestAnimationFrame(() => requestAnimationFrame(sync));
  window.addEventListener('resize', () => setTimeout(sync, 120));
  wrap.__lensSync = sync;
}
function initAddTabsLens() { initSegLens($('#addTabs')); }
function initTrendSegLens() { initSegLens($('#trendSeg')); }

function setAddMode(m) {
  S.addMode = m;
  $$('#addTabs button').forEach(b => b.classList.toggle('on', b.dataset.m === m));
  ['photo', 'search', 'text'].forEach(k => {
    $('#pane-' + k).hidden = k !== m;
  });
  if (m === 'search') {
    $('#searchList').hidden = false;              // 回到搜索就一定能继续挑
    runSearch($('#searchInput').value || '');
    // 每次进来都回到列表最上面（相当于重新开始挑）
    const sb = document.querySelector('#addSheet .sh-body');
    if (sb) sb.scrollTop = 0;
  }
  if (window.__addTabsLens) requestAnimationFrame(() => window.__addTabsLens.sync());
}

function renderMealPick() {
  $$('#mealPick .chip').forEach(c => c.classList.toggle('on', c.dataset.meal === S.meal));
}

function renderRecent() {
  const box = $('#recentChips');
  const seen = [];
  (S.day?.logs || []).forEach(l => {
    if (!seen.includes(l.name)) seen.push(l.name);
  });
  const picks = seen.slice(0, 6);
  if (picks.length < 4) {
    ['鸡蛋', '米饭', '牛奶(全脂)', '鸡胸肉(生)', '香蕉'].forEach(n => {
      if (!picks.includes(n)) picks.push(n);
    });
  }
  box.innerHTML = picks.slice(0, 7).map(n =>
    `<button class="chip" data-quick="${esc(n)}">${esc(n)}</button>`).join('');
  $$('[data-quick]', box).forEach(b => b.onclick = () => {
    const f = S.foods.find(x => x.name === b.dataset.quick);
    if (f) pushFood(f);
  });
}

/* ---- 拍照 ---- */
async function compress(file, max = 1280, q = 0.82) {
  const bmp = await new Promise((res, rej) => {
    if (window.createImageBitmap) {
      createImageBitmap(file).then(res).catch(rej);
    } else {
      const img = new Image();
      img.onload = () => res(img);
      img.onerror = rej;
      img.src = URL.createObjectURL(file);
    }
  });
  const scale = Math.min(1, max / Math.max(bmp.width, bmp.height));
  const c = document.createElement('canvas');
  c.width = Math.round(bmp.width * scale);
  c.height = Math.round(bmp.height * scale);
  c.getContext('2d').drawImage(bmp, 0, 0, c.width, c.height);
  return c.toDataURL('image/jpeg', q);
}

async function handlePhoto(file) {
  if (!file) return;
  try {
    if (S.photoURL) URL.revokeObjectURL(S.photoURL);
    S.photoURL = URL.createObjectURL(file);
    $('#photoPreview').src = S.photoURL;
    $('#photoPreview').hidden = false;
    $('#photoDel').hidden = false;
    $('#emptyA').hidden = true;
    S.photoData = await compress(file);
    S.photoAt = Date.now();
    $('#photoActions').hidden = false;
    saveDraft();
  } catch (e) {
    toast('图片读取失败');
  }
}

/* 一组按钮：先填 ① 食物照片，再填 ② 营养成分表 */
async function handlePick(file) {
  if (!file) return;
  if (!S.photoData) return handlePhoto(file);
  if (!S.photo2Data) return handlePhoto2(file);
  toast('两张都拍好了。点照片上的 × 可以换一张', 3000);
}

async function handlePhoto2(file) {
  if (!file) return;
  try {
    if (S.photo2URL) URL.revokeObjectURL(S.photo2URL);
    S.photo2URL = URL.createObjectURL(file);
    $('#pv2').src = S.photo2URL;
    $('#pv2').hidden = false;
    $('#del2').hidden = false;
    $('#emptyB').hidden = true;
    S.photo2Data = await compress(file, 1024, 0.8);
    saveDraft();
  } catch (e) {
    toast('图片读取失败');
  }
}

/* ---------------- 拍照草稿：关掉卡片 / 退出 App 也不丢 ---------------- */
const DRAFT_KEY = 'calorie-ledger-draft';
function readDraft() {
  try {
    const raw = localStorage.getItem(DRAFT_KEY);
    if (!raw) return null;
    const d = JSON.parse(raw);
    if (!d || !d.at || Date.now() - d.at > 24 * 3600e3) { localStorage.removeItem(DRAFT_KEY); return null; }
    return d;
  } catch (e) { return null; }
}
function saveDraft() {
  const d = { photo: S.photoData || null, photo2: S.photo2Data || null, at: Date.now() };
  try {
    if (!d.photo && !d.photo2) localStorage.removeItem(DRAFT_KEY);
    else localStorage.setItem(DRAFT_KEY, JSON.stringify(d));
  } catch (e) { /* 存不下就算了 */ }
}
function clearDraft() {
  try { localStorage.removeItem(DRAFT_KEY); } catch (e) {}
}
/* 把草稿里的照片放回界面 */
function restoreDraft() {
  const d = readDraft();
  if (!d) return;
  if (d.photo) {
    S.photoData = d.photo;
    $('#photoPreview').src = d.photo;
    $('#photoPreview').hidden = false;
    $('#photoDel').hidden = false;
    $('#emptyA').hidden = true;
  }
  if (d.photo2) {
    S.photo2Data = d.photo2;
    $('#pv2').src = d.photo2;
    $('#pv2').hidden = false;
    $('#del2').hidden = false;
    $('#emptyB').hidden = true;
  }
  if (d.photo || d.photo2) $('#photoActions').hidden = false;
}

/* 把拍照区恢复成「还没选图」的样子 */
function resetPhotoUI() {
  if (S.photoURL) { URL.revokeObjectURL(S.photoURL); S.photoURL = null; }
  const pv = $('#photoPreview');
  pv.removeAttribute('src');
  pv.hidden = true;
  $('#photoDel').hidden = true;
  $('#emptyA').hidden = false;
  S.photoData = null;
  S.photoAt = null;
  $('#photoDrop').hidden = false;
  $('#pane-photo').classList.remove('done');
  $('#photoActions').hidden = true;
  if (S.photo2URL) { URL.revokeObjectURL(S.photo2URL); S.photo2URL = null; }
  S.photo2Data = null;
  $('#pv2').removeAttribute('src');
  $('#pv2').hidden = true;
  $('#del2').hidden = true;
  $('#emptyB').hidden = false;
}

async function runPhoto() {
  const main = S.photoData || S.photo2Data;
  if (!main) return toast('先拍一张照片');
  const btn = $('#photoGo');
  const old = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span> 识别中…';
  try {
    const grams = Number(($('#photoGrams') || {}).value) || 0;
    const dishName = (($('#photoName') || {}).value || '').trim();
    let hint = $('#photoHint').value.trim();
    if (dishName) hint = '用户说这是：' + dishName + '（请按这个食材估算，不要换品种）' + (hint ? '；' + hint : '');
    let modeHint;
    if (S.photoData && S.photo2Data) {
      modeHint = '第一张图是实际吃的食物本体，第二张图是包装上的营养成分表。'
        + '请按第二张的标签读每 100 克的能量/蛋白质/碳水/脂肪（不要用外观估算这几项），'
        + '再按第一张估算实际吃掉了多少克；两两相乘得到总量。';
    } else if (S.photoData) {
      modeHint = '这张图是食物本体：按外观和常见餐具尺寸估算实际吃掉的重量。';
    } else {
      modeHint = '这张图是包装上的营养成分表：每 100 克数值只按标签读数；name 用产品名。';
    }
    hint = hint ? modeHint + '；' + hint : modeHint;
    if (grams > 0) hint = hint + `；我实际吃了 ${grams} 克`;
    // 有食物图就用它当主图；只拍了成分表就反过来
    const hasFood = !!S.photoData;
    const r = await api('/api/ai/food', {
      image: hasFood ? S.photoData : S.photo2Data,
      image2: hasFood ? (S.photo2Data || null) : null,
      hint,
    });
    S.items = r.items.map(x => ({ ...x, _src: 'photo' }));
    // 填了克数就以它为准（包装营养表通常只有一条）
    if (grams > 0 && S.items.length === 1) S.items[0].grams = grams;
    // 识别完就把大图收起，结果区（左小图 + 右数值）直接露出来
    $('#photoDrop').hidden = true;
    $('#photoActions').hidden = true;
    $('#pane-photo').classList.add('done');
    S.batchName = r.dish || '';
    $('#batchName').value = S.batchName;
    showResult(r.dish ? '识别：' + r.dish : '识别结果', r.note);
  } catch (e) {
    toast(e.message, 5000);
  } finally {
    btn.disabled = false;
    btn.innerHTML = old;
  }
}

/* 存一张小图（约 10~20KB），之后点开这一组还能看到当时拍的 */
async function makeThumb(dataUrl, max = 320, q = 0.55) {
  const img = await new Promise((res, rej) => {
    const i = new Image();
    i.onload = () => res(i);
    i.onerror = rej;
    i.src = dataUrl;
  });
  const scale = Math.min(1, max / Math.max(img.width, img.height));
  const c = document.createElement('canvas');
  c.width = Math.round(img.width * scale);
  c.height = Math.round(img.height * scale);
  c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
  return c.toDataURL('image/jpeg', q);
}

/* ---- 文字 ---- */
async function runText() {
  const text = $('#textInput').value.trim();
  if (!text) return toast('先描述一下吃了什么');
  const btn = $('#textGo');
  const old = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span> 估算中…';
  try {
    const r = await api('/api/ai/text', { text });
    S.items = r.items.map(x => ({ ...x, _src: 'ai' }));
    S.batchName = r.dish || '';
    $('#batchName').value = S.batchName;
    showResult(r.dish ? '估算：' + r.dish : '估算结果', r.note);
  } catch (e) {
    toast(e.message, 5000);
  } finally {
    btn.disabled = false;
    btn.innerHTML = old;
  }
}

/* ---- 搜索 ---- */

/* 记过的食物 = 一份永久名单（Store.foodHist）：记一次就永久保存，只有用户点 × 才删。
   早期版本是"从日志里反推"，日志被删/被清就消失了，所以换成独立名单。 */
function rememberFoods(items) {
  const st = Store.load();
  if (!Array.isArray(st.foodHist)) st.foodHist = [];
  const dels = new Set(st.foodHistDel || []);
  (items || []).forEach(it => {
    const name = String(it.name || '').trim();
    const g = Number(it.grams) || 0;
    if (!name || !g) return;
    const per100 = (v, digits) => +(Number(v || 0) * 100 / g).toFixed(digits);
    const rec = {
      n: name,
      k: Math.round(per100(it.kcal_per_100g, 0)),
      p: per100(it.protein_per_100g, 1),
      c: per100(it.carb_per_100g, 1),
      f: per100(it.fat_per_100g, 1),
      g,                                  // 上次用的克数，下次默认带出来
      cat: it.cat || '以前记过',
      at: Date.now(),
    };
    // 记住这个食物这次用的克数（下次添加/编辑都用它，不再推荐别的数字）
    st.settings = st.settings || {};
    st.settings.food_grams = Object.assign({}, st.settings.food_grams || {}, { [name]: +Number(g).toFixed(1) });
    const i = st.foodHist.findIndex(x => x.n === name);
    if (i >= 0) st.foodHist[i] = Object.assign({}, st.foodHist[i], rec);
    else st.foodHist.push(rec);
    dels.delete(name);                    // 手动记一次 = 重新加回名单
  });
  if (dels.size) st.foodHistDel = [...dels];
  Store.save();
}

/* 记住某个食物这次填的克数（下次添加同名的食物就用这个数） */
function rememberGrams(name, grams) {
  const g = Number(grams);
  if (!name || !(g > 0)) return;
  const st = Store.load();
  st.settings = st.settings || {};
  st.settings.food_grams = Object.assign({}, st.settings.food_grams || {}, { [String(name)]: +g.toFixed(1) });
  Store.save();
}

function forgetFood(name) {
  const st = Store.load();
  st.foodHist = (st.foodHist || []).filter(x => x.n !== name);
  st.foodHistDel = Array.from(new Set([...(st.foodHistDel || []), name]));
  Store.save();
}

/* 记过的食物（按最近一次用的时间倒序） */
function historyFoods() {
  const st = Store.load();
  if (!Array.isArray(st.foodHist)) st.foodHist = [];
  // 一次性把老日志里的食物补进名单（补过就不再补，删掉的不会自己回来）
  if (!st.settings.histBackfilled) {
    const has = new Set(st.foodHist.map(x => x.n));
    (st.logs || []).forEach(l => {
      const g = Number(l.grams) || 0;
      const name = String(l.name || '').trim();
      if (!g || !name || has.has(name)) return;
      has.add(name);
      st.foodHist.push({
        n: name,
        k: Math.round((Number(l.kcal) || 0) * 100 / g),
        p: +(((Number(l.p) || 0) * 100) / g).toFixed(1),
        c: +(((Number(l.c) || 0) * 100) / g).toFixed(1),
        f: +(((Number(l.f) || 0) * 100) / g).toFixed(1),
        g, cat: '以前记过', at: Number(l.ts) || 0,
      });
    });
    st.settings.histBackfilled = 1;
    Store.save({ silent: true });
  }
  const dels = new Set(st.foodHistDel || []);
  return st.foodHist
    .filter(x => !dels.has(x.n))
    .sort((a, b) => (b.at || 0) - (a.at || 0))
    .map(x => ({ name: x.n, kcal: x.k, p: x.p, c: x.c, f: x.f, grams: x.g, cat: x.cat || '以前记过' }));
}

/* 有结果在下面时先把搜索列表收起来（选完直接看到记录区）；结果清空后再放出来 */
function syncSearchList() {
  const box = $('#searchList');
  if (!box) return;
  box.hidden = (S.items || []).length > 0;
}

function runSearch(q) {
  const box = $('#searchList');
  const key = q.trim().toLowerCase();
  const hist = historyFoods();

  let list;
  if (!key) {
    list = hist.slice(0, 12).map(f => ({ f, h: true }));
  } else {
    const h = hist.filter(f => f.name.toLowerCase().includes(key)).map(f => ({ f, h: true }));
    const db = S.foods
      .filter(f => f.name.toLowerCase().includes(key) ||
        (f.alias || []).some(a => a.toLowerCase().includes(key)))
      .filter(f => !h.some(x => x.f.name === f.name))
      .slice(0, 20)
      .map(f => ({ f, h: false }));
    list = h.concat(db);
  }

  if (!list.length) {
    box.innerHTML = key
      ? `<div class="empty-state">库里没有「${esc(q)}」<br>试试换个说法，或用「描述」让 AI 估</div>`
      : '';
    return;
  }

  box.innerHTML = list.map((x, i) => `
    <div class="sitem" data-i="${i}">
      <div>
        <div>${esc(x.f.name)}${x.h ? ' <span style="font-size:9px;color:var(--lime)">记过</span>' : ''}</div>
        <div class="cat">${esc(x.f.cat || '')} · 蛋白 ${x.f.p}g / 碳水 ${x.f.c}g / 脂肪 ${x.f.f}g</div>
      </div>
      <div class="kc">${x.f.kcal}<br><span style="font-size:9px">/100g</span></div>
      ${x.h ? `<button class="hdel" data-del="${esc(x.f.name)}" aria-label="从历史里删除">
        <svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M3 3l6 6M9 3l-6 6"/></svg>
      </button>` : ''}
    </div>`).join('');

  // × 只从这个历史名单里删（不影响已经记过的账），点它不会顺手把食物加进去
  $$('.hdel', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    const n = b.dataset.del;
    forgetFood(n);
    toast(`已从历史里删除「${n}」`, 2000);
    runSearch($('#searchInput').value || '');
  });

  $$('.sitem', box).forEach(el => el.onclick = () => {
    pushFood(list[Number(el.dataset.i)].f);
    // 选中后：搜索这边清空回初始状态（清空搜索词、列表滚回顶部），
    // 然后把界面切到左边的「拍照」—— 记录区在那边，加进来的都列在那里
    $('#searchInput').value = '';
    $('#searchInput').blur();
    $('#searchList').hidden = false;
    runSearch('');
    const sb = document.querySelector('#addSheet .sh-body');
    if (sb) sb.scrollTop = 0;
    setAddMode('photo');
  });
}

function pushFood(f) {
  // 上次这个食物记了多少克，这次就用多少克（不再用它自带的推荐值）
  const remembered = (setting('food_grams', {}) || {})[f.name];
  const def = Number(remembered) || Number(f.grams) || (f.units && f.units[0] ? f.units[0].g : 100);
  S.items.push({
    name: f.name,
    grams: def,
    kcal_per_100g: f.kcal,
    protein_per_100g: f.p,
    carb_per_100g: f.c,
    fat_per_100g: f.f,
    confidence: 1,
    _src: 'db',
    _units: f.units || [],
  });
  showResult('已添加', '');
}

/* ---- 结果编辑 ---- */
function showResult(title, note) {
  $('#resultArea').hidden = S.items.length === 0;
  $('#resultTitle').textContent = title || '识别结果';
  $('#resultNote').textContent = note || '';
  $('#addFoot').hidden = S.items.length === 0;
  renderResult();
  requestAnimationFrame(() => {
    const ra = $('#resultArea');
    if (!ra.hidden) ra.scrollIntoView({ block: 'start', behavior: 'smooth' });
  });
}

function renderResult() {
  syncSearchList();
  const box = $('#resultItems');
  let shot = '';
  // 拍的是什么就显示什么：拍实物 →「食物照片」，拍营养成分表 →「营养成分表照片」；
  // 两样都拍了就两行都列出来，各自配各自的图
  if (S.photoData || S.photo2Data) {
    const two = !!(S.photoData && S.photo2Data);
    const shotThumb = (src, cap) => `<span class="sthumb"><img src="${src}" alt=""><i>${cap}</i></span>`;
    const thumbs = [
      S.photoData ? shotThumb(S.photoData, '食物') : '',
      S.photo2Data ? shotThumb(S.photo2Data, '营养表') : '',
    ].join('');
    const title = two ? '食物照片 + 营养成分表' : (S.photo2Data ? '营养成分表照片' : '食物照片');
    const sub = two ? `识别出 ${S.items.length} 项 · 克数可改`
                    : (S.photo2Data ? '按标签每 100 克换算' : `识别出 ${S.items.length} 项 · 克数可改`);
    shot = `<div class="shotrow">
      <div class="sthumbs">${thumbs}</div>
      <div class="sinfo">
        <b>${title}</b>
        <span>${sub}</span>
      </div>
    </div>`;
  }
  $('#shotBox').innerHTML = shot;
  // 多项才需要给这一餐起名（识别到的菜名会自动填进来）
  $('#nameWrap').hidden = S.items.length < 2;
  box.innerHTML = S.items.map((it, i) => {
    const kcal = it.kcal_per_100g * it.grams / 100;
    const units = (it._units || []).filter(u => u.g !== 100).slice(0, 3);
    const chips = units.map(u =>
      `<button data-u="${i}" data-g="${u.g}">${u.unit}</button>`).join('');
    const low = it.confidence != null && it.confidence < 0.55;
    return `
      <div class="ritem" data-low="${low ? 1 : 0}" data-row="${i}">
        <button class="del" data-rm="${i}" aria-label="删掉这一项">×</button>
        <div class="top">
          <span class="nm">${nameLine(it.name, `data-ren="${i}"`)}</span>
        </div>
        <div class="meta"><span class="mtxt">每 100g ${Math.round(it.kcal_per_100g)} 千卡 · 蛋 ${it.protein_per_100g}/碳 ${it.carb_per_100g}/脂 ${it.fat_per_100g}${low ? ' · 不太确定' : ''}</span><button class="pen" data-nut="${i}" aria-label="改营养数据">${PEN_ICON}</button></div>
        <div class="gr">
          <input type="number" inputmode="decimal" value="${it.grams}" data-g="${i}">
          <span class="u">克</span>
          <div class="chips">${chips}</div>
          <span class="kc">${Math.round(kcal)}</span>
        </div>
      </div>`;
  }).join('');

  const total = S.items.reduce((a, b) => a + b.kcal_per_100g * b.grams / 100, 0);
  $('#resultTotal').textContent = Math.round(total);
  $('#addFoot').hidden = S.items.length === 0;
  $('#resultArea').hidden = S.items.length === 0;

  // 删掉某一项；如果都删光了，上面那两张照片也跟着清掉
  $$('[data-rm]', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    S.items.splice(Number(b.dataset.rm), 1);
    if (!S.items.length) resetPhotoUI();
    renderResult();
  });
  $$('[data-ren]', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    const it = S.items[Number(b.dataset.ren)];
    if (!it) return;
    const name = prompt('这个食物叫什么？', it.name || '');
    if (name === null) return;
    const v = name.trim().slice(0, 20);
    if (!v) return;
    it.name = v;
    renderResult();
  });
  $$('[data-nut]', box).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    openNutEdit(Number(b.dataset.nut));
  });
  $$('[data-u]', box).forEach(b => b.onclick = () => {
    S.items[Number(b.dataset.u)].grams = Number(b.dataset.g);
    renderResult();
  });
  $$('input[data-g]', box).forEach(inp => {
    inp.oninput = () => {
      S.items[Number(inp.dataset.g)].grams = Number(inp.value) || 0;
      rememberGrams(S.items[Number(inp.dataset.g)].name, inp.value);
      const kc = S.items[Number(inp.dataset.g)];
      const el = inp.closest('.ritem').querySelector('.kc');
      el.textContent = Math.round(kc.kcal_per_100g * kc.grams / 100);
      const total = S.items.reduce((a, b) => a + b.kcal_per_100g * b.grams / 100, 0);
      $('#resultTotal').textContent = Math.round(total);
    };
  });
}

/* ---------------- 改某一项的营养数据 ----------------
   场景：包装上写的是「每份 12.5 克 · 60 千卡」，早先被当成「每 100 克」记了。
   这里按"参考量多少克 + 那份的营养"来填，保存时换算成每 100 克。 */
let nutEditIdx = -1;
let nutLogId = null;        // 非空 = 正在编辑"已经记过的一条"
function openNutEdit(i, fake) {
  const it = fake || S.items[i];
  if (!it) return;
  nutEditIdx = fake ? -1 : i;
  if (!fake) nutLogId = null;
  // 预填成"这一份"的实际数值（参考量 = 当前克数），保存时再换算回每 100 克
  const g = Number(it.grams) || 100;
  const share = g / 100;
  setNutUnit('kJ', false);                        // 默认按千焦（包装上绝大多数写的是千焦）
  const kcalOfPortion = (Number(it.kcal_per_100g) || 0) * share;
  $('#nutRef').value = +g.toFixed(1);
  $('#nutKcal').value = nutUnit === 'kJ' ? Math.round(kcalOfPortion * KJ_PER_KCAL) : Math.round(kcalOfPortion);
  $('#nutP').value = +(((Number(it.protein_per_100g) || 0) * share).toFixed(1));
  $('#nutC').value = +(((Number(it.carb_per_100g) || 0) * share).toFixed(1));
  $('#nutF').value = +(((Number(it.fat_per_100g) || 0) * share).toFixed(1));
  const nq0 = $('#nutNameQ'); if (nq0) nq0.value = it.name || '';
  const sug0 = $('#nutSug'); if (sug0) { sug0.hidden = true; sug0.innerHTML = ''; }
  nutBase = { k: Number(it.kcal_per_100g) || 0, p: Number(it.protein_per_100g) || 0,
              c: Number(it.carb_per_100g) || 0, f: Number(it.fat_per_100g) || 0 };
  nutDirty = { k: false, p: false, c: false, f: false };
  paintNutPreview();
  // 位置：弹在记录卡片的垂直正中间（等它显示出来量到真实高度后再定位，误差 0）
  const sh = $('#nutSheet');
  sh.style.top = '';
  sh.style.bottom = '';
  // 遮罩和面板一起往上抬两级：遮罩在面板下一层，但要在"别的卡片的遮罩"之上，
  // 否则点外面时第一下命中别人的遮罩（先暗一次）、第二下才关这个面板
  const nm = $('#nutMask');
  if (nm) nm.style.zIndex = String(++sheetZ);
  sh.style.zIndex = String(++sheetZ);
  // 同样：先落位（关过渡）→ 再显示，避免"先出现在底部再跳到中间"
  sh.classList.add('noanim');
  {
    // 量两次：第一次排好版，第二次拿到"预览行换行之后"的真实高度
    // 用 offsetHeight（不受 transform: scale 影响），否则会算小、卡片往下溢出屏幕
    const place = () => {
      const bigEl = $('#addSheet');
      const bigOpen = bigEl && bigEl.classList.contains('on');
      // 从记录卡片里打开 → 对齐那张卡片；从"今天吃了什么"直接打开（卡片没开）→ 对齐屏幕
      const centerY = bigOpen
        ? bigEl.getBoundingClientRect().top + bigEl.getBoundingClientRect().height / 2
        : window.innerHeight / 2;
      const h = sh.offsetHeight || 0;
      const top = Math.max(8, Math.min(centerY - h / 2, window.innerHeight - h - 8));
      sh.style.top = Math.round(top) + 'px';
      sh.style.bottom = 'auto';
    };
    place();
    paintNutPreview();
    void sh.offsetHeight;
    place();
  }
  sh.classList.remove('noanim');
  $('#nutMask').classList.add('on');
  sh.classList.add('on');
  setTimeout(() => $('#nutRef').focus(), 260);
}
/* 从"今天吃了什么"或某一组明细里点那个「…」：改一条已记录的账 */
function openNutEditLog(id) {
  const l = (Store.load().logs || []).find(x => x.id === Number(id));
  if (!l) return;
  const g = Number(l.grams) || 0;
  const k = g ? (Number(l.kcal) || 0) * 100 / g : 0;
  nutLogId = l.id;
  openNutEdit(-1, {
    name: l.name,
    grams: g,
    kcal_per_100g: k,
    protein_per_100g: g ? (Number(l.p) || 0) * 100 / g : 0,
    carb_per_100g: g ? (Number(l.c) || 0) * 100 / g : 0,
    fat_per_100g: g ? (Number(l.f) || 0) * 100 / g : 0,
  });
}

function closeNutEdit() {
  $('#nutMask').classList.remove('on');
  const sh = $('#nutSheet');
  // 和 closeAdd 一样：下滑关闭时脚本写过 transform / opacity，这里必须当场清掉，
  // 否则下次打开会停在半路 —— 这就是"营养卡片下滑卡住"的真正原因
  sh.classList.remove('dragging');
  sh.style.transform = '';
  sh.style.opacity = '';
  sh.classList.remove('on');
  setTimeout(() => { sh.style.top = ''; sh.style.bottom = ''; }, 420);
  nutEditIdx = -1;
}
let nutUnit = 'kcal';
let nutBase = { k: 0, p: 0, c: 0, f: 0 };   // 上面那格记住"每 100 克"的原始值
let nutDirty = { k: false, p: false, c: false, f: false };   // 用户手改过的格子，改克数时不被覆盖
const KJ_PER_KCAL = 4.184;
function setNutUnit(u, convert) {
  const inp = $('#nutKcal');
  const v = Number(inp.value) || 0;
  if (convert && v > 0) {
    inp.value = u === 'kJ' ? Math.round(v * KJ_PER_KCAL) : Math.round(v / KJ_PER_KCAL);
  }
  nutUnit = u;
  // 切换单位时把已经显示的数值按新单位写回基准（这样之后改克数仍然按每 100 克等比）
  const curRef = Number($('#nutRef').value) || 0;
  if (convert && curRef > 0) {
    const kEl2 = $('#nutKcal');
    const shown = Number(kEl2 && kEl2.value) || 0;
    if (shown > 0) nutBase = Object.assign({}, nutBase, { k: u === 'kJ' ? (shown / KJ_PER_KCAL) * 100 / curRef : shown * 100 / curRef });
  }
  const now = $('#nutUnitNow');
  if (now) now.textContent = u === 'kJ' ? '千焦' : '千卡';
  if (inp) inp.placeholder = u === 'kJ' ? '8904' : '2128';
}

/* 边填边算：让用户当场看到「这一份 = 每 100 克多少」 */
/* 面板里按食物名找库/历史，找到就把"这一份"的营养填进来（用户只知道克数、不知道千焦时用） */
function nutFindFoods(q) {
  const key = String(q || '').trim();
  if (!key) return [];
  const norm = (x) => String(x || '').toLowerCase();
  const k = norm(key);
  const hist = historyFoods().filter(f => norm(f.name).includes(k))
    .map(f => ({ name: f.name, kcal: f.kcal, p: f.p, c: f.c, f: f.f, from: '历史' }));
  const fromDb = (S.foods || []).filter(f => norm(f.name).includes(k) ||
      (f.alias || []).some(a => norm(a).includes(k)))
    .map(f => ({ name: f.name, kcal: f.kcal, p: f.p, c: f.c, f: f.f, from: '食物库' }));
  const seen = new Set();
  return hist.concat(fromDb).filter(f => (seen.has(f.name) ? false : (seen.add(f.name), true))).slice(0, 6);
}

function applyNutFood(f) {
  const ref = Number($('#nutRef').value) || 100;
  const share = ref / 100;
  const k = Number(f.kcal) || 0;
  $('#nutKcal').value = Math.round(nutUnit === 'kJ' ? k * share * KJ_PER_KCAL : k * share);
  $('#nutP').value = +(((Number(f.p) || 0) * share).toFixed(1));
  $('#nutC').value = +(((Number(f.c) || 0) * share).toFixed(1));
  $('#nutF').value = +(((Number(f.f) || 0) * share).toFixed(1));
  const sug = $('#nutSug');
  if (sug) { sug.hidden = true; sug.innerHTML = ''; }
  const q = $('#nutNameQ');
  if (q) q.value = f.name;
  paintNutPreview();
}

function paintNutPreview() {
  const box = $('#nutPreview');
  if (!box) return;                       // 这行已经删掉，函数留着不影响
  const ref = Number($('#nutRef').value) || 0;
  const raw = $('#nutKcal').value.trim();
  const kcal = raw === '' ? NaN : Number(raw);
  if (!(ref > 0) || !isFinite(kcal)) { box.textContent = '填了参考量和热量，这里会显示换算结果'; return; }
  const per100 = nutUnit === 'kJ' ? (kcal / KJ_PER_KCAL) * 100 / ref : kcal * 100 / ref;
  const unit = nutUnit === 'kJ' ? '千焦' : '千卡';
  box.innerHTML = `这 ${+ref.toFixed(1)} 克 = <b>${Math.round(kcal)} ${unit}</b>　→　每 100 克 = <b>${Math.round(per100)} 千卡</b>`;
}

function saveNutEdit() {
  // 两种目标：草稿里的一项（S.items）或已经记过的一条（nutLogId）
  const logTarget = nutLogId ? (Store.load().logs || []).find(x => x.id === nutLogId) : null;
  const it = logTarget ? { name: logTarget.name } : S.items[nutEditIdx];
  if (!it) return closeNutEdit();
  const ref = Number($('#nutRef').value);
  const kcalRaw = $('#nutKcal').value.trim();
  if (!(ref > 0)) return toast('参考量必须填（这份多少克）', 2600);
  if (kcalRaw === '' || !(Number(kcalRaw) >= 0)) return toast('热量必须填（千卡）', 2600);
  const k = 100 / ref;                            // 换算到每 100 克
  it.grams = +ref.toFixed(1);                     // 参考量就是"这一份吃多少克"，写回克数
  rememberGrams(it.name, ref);                     // 记住这个食物的克数，下次直接用
  const kcalIn = nutUnit === 'kJ' ? (Number(kcalRaw) / KJ_PER_KCAL) : Number(kcalRaw);   // 千焦先换成千卡
  const num = (sel) => { const v = $(sel).value.trim(); return v === '' ? 0 : Number(v) || 0; };
  it.kcal_per_100g = +(kcalIn * k).toFixed(1);
  it.protein_per_100g = +(num('#nutP') * k).toFixed(1);
  it.carb_per_100g = +(num('#nutC') * k).toFixed(1);
  it.fat_per_100g = +(num('#nutF') * k).toFixed(1);
  const idx = nutEditIdx;
  // 改的是"已经记过的一条"：直接改那条记录，然后重算当天
  if (nutLogId) {
    const d = Store.load();
    const l = (d.logs || []).find(x => x.id === nutLogId);
    if (l) {
      l.grams = +ref.toFixed(1);
      rememberGrams(l.name, ref);
      l.kcal = Math.round(kcalIn * 10) / 10;
      l.p = +(num('#nutP')).toFixed(1);
      l.c = +(num('#nutC')).toFixed(1);
      l.f = +(num('#nutF')).toFixed(1);
      Store.save();
    }
    const wasGroup = S.detailIsGroup, ids = (S.detailIds || []).slice(), tname = S.detailName;
    closeNutEdit();
    closeGroup();
    toast(`已更新：${it.name} ${l ? l.grams : ref} 克 · ${Math.round(kcalIn)} 千卡`, 2600);
    loadDay().then(() => {
      if (wasGroup || ids.length) {
        const fresh = (Store.load().logs || []).filter(x => ids.includes(x.id));
        if (fresh.length) openDetail(fresh, wasGroup, tname);
      }
    });
    return;
  }
  closeNutEdit();
  renderResult();                                 // 热量、合计当场重算
  // 双保险：外面那一项的克数框 / 每 100 克那行 / 热量，全部直接写成新值
  // （哪怕重绘时序出问题，用户也能立刻看到变化）
  const row = document.querySelector(`#resultItems .ritem[data-row="${idx}"]`)
           || document.querySelectorAll('#resultItems .ritem')[idx];
  if (row) {
    const gi = row.querySelector('input[data-g]');
    if (gi) gi.value = it.grams;
    const mt = row.querySelector('.meta .mtxt');
    if (mt) mt.textContent = `每 100g ${Math.round(it.kcal_per_100g)} 千卡 · 蛋 ${it.protein_per_100g}/碳 ${it.carb_per_100g}/脂 ${it.fat_per_100g}`;
    const kc = row.querySelector('.kc');
    if (kc) kc.textContent = Math.round(it.kcal_per_100g * it.grams / 100);
  }
  const tot = document.querySelector('#resultTotal');
  if (tot) tot.textContent = Math.round(S.items.reduce((a, b) => a + b.kcal_per_100g * b.grams / 100, 0));
  toast(`已更新：这一份 ${it.grams} 克 · ${Math.round(it.kcal_per_100g * it.grams / 100)} 千卡`, 2600);
}

async function saveItems() {
  const items = S.items.filter(i => i.grams > 0);
  if (!items.length) return toast('没有可保存的条目');
  const dishName = ($('#batchName').value || '').trim().slice(0, 20);
  if (items.length > 1 && !dishName) {
    $('#batchName').focus();
    return toast('先给这一餐起个名字，比如「沙县小吃」', 3000);
  }
  const btn = $('#saveItems');
  btn.disabled = true;
  btn.textContent = '保存中…';
  try {
    const batch = 'b' + Date.now();
    let shot = '';
    const thumbSrc = S.photoData || S.photo2Data;
    if (batch && thumbSrc) {
      try { shot = await makeThumb(thumbSrc); } catch (e) { /* 图存不下就算了 */ }
    }
    await api('/api/logs', {
      date: S.date,
      meal: S.meal,
      items,
      source: items[0]._src || 'manual',
      // 一次识别出来的多项合成一组，列表里只占一行
      batch,
      batchName: items.length > 1 ? dishName : '',
      shot,
    });
    rememberFoods(items);                 // 记过的食物永久留档（搜索里能找到，× 才删）
    closeAdd();
    S.batchName = null;
    clearDraft();
    toast(`已记入${MEAL_NAME[S.meal]} · ${Math.round(items.reduce((a, b) => a + b.kcal_per_100g * b.grams / 100, 0))} 千卡`);
    await loadDay();
    if (S.view === 'trends') loadTrends();
  } catch (e) {
    toast(e.message, 4000);
  } finally {
    btn.disabled = false;
    btn.textContent = '记入';
  }
}


/* ---------------- 一组记录的详情卡片 ---------------- */
function openGroup(key) {
  const g = groupMap.get(key);
  if (!g) return;
  openDetail(g.logs, true, g.name || '未命名');
}

/* logs：这一组（或这一条）记录；isGroup：多条才显示「N 项」和小计 */
function openDetail(logs, isGroup, title) {
  if (!logs || !logs.length) return;
  const sum = k => Math.round(logs.reduce((a, b) => a + (b[k] || 0), 0));
  const kcal = Math.round(logs.reduce((a, b) => a + (b.kcal || 0), 0));
  const batchKey = logs[0].batch || '';
  const shot = (S.day && S.day.shots && S.day.shots[batchKey]) || '';
  $('#grpNameTxt').textContent = title || logs[0].name;
  $('#grpMeta').textContent = isGroup
    ? `${logs.length} 项 · 蛋${sum('p')} / 碳${sum('c')} / 脂${sum('f')}`
    : `${Math.round(logs[0].grams)}g`;
  const img = $('#grpShot');
  if (shot) { img.src = shot; img.hidden = false; } else { img.removeAttribute('src'); img.hidden = true; }
  // 拍照记的却没有图 → 说明是旧版本记的，说清楚免得以为丢了
  const noShot = !shot && logs.some(l => l.source === 'photo');
  const tip = $('#grpNoShot');
  if (tip) tip.hidden = !noShot;
  $('#grpItems').innerHTML = logs.map(l => `
    <div class="gitem">
      <div class="n">${esc(l.name)}<span class="sub">${g1(l.grams)}g · 蛋${g1(l.p)}·碳${g1(l.c)}·脂${g1(l.f)}<button class="pen inl" data-nutlog="${l.id}" aria-label="改营养数据">${PEN_ICON}</button></span></div>
      <div class="k">${Math.round(l.kcal)}</div>
      <button class="del" data-gdel="${l.id}">×</button>
    </div>`).join('');
  $('#grpTotal').textContent = kcal;
  S.detailIds = logs.map(l => l.id);
  S.detailIsGroup = !!isGroup;
  S.detailName = title || logs[0].name;
  $$('[data-nutlog]', $('#grpItems')).forEach(b => b.onclick = ev => {
    ev.stopPropagation();
    openNutEditLog(b.dataset.nutlog);
  });
  $$('[data-gdel]', $('#grpItems')).forEach(b => b.onclick = async ev => {
    ev.stopPropagation();
    try {
      await api('/api/logs/' + b.dataset.gdel, null, 'DELETE');
      closeGroup();
      await loadDay();
    } catch (e) { toast(e.message); }
  });
  $('#grpMask').classList.add('on');
  $('#grpSheet').classList.add('on');
}
function closeGroup() {
  $('#grpMask').classList.remove('on');
  $('#grpSheet').classList.remove('on');
}
async function renameGroup() {
  if (!S.detailIds) return;
  const name = prompt(S.detailIsGroup ? '这份叫什么？（比如：沙县小吃）' : '这个食物叫什么？', S.detailName || '');
  if (name === null) return;
  const v = name.trim().slice(0, 20);
  if (!v) return;
  try {
    await api('/api/logs/rename', { ids: S.detailIds, name: v, item: !S.detailIsGroup });
    closeGroup();
    await loadDay();
  } catch (e) { toast(e.message); }
}

/* ---------------- 趋势 ---------------- */
async function loadTrends() {
  try {
    const t = await api('/api/trends?days=' + S.trendDays);
    S.trend = t;
    renderTrends();
  } catch (e) {
    toast(e.message);
  }
}

function wireTrendChart() {
  const wrap = document.querySelector('#trWrap');
  if (!wrap) return;
  wrap.querySelectorAll('circle[data-d]').forEach(c => {
    c.style.cursor = 'pointer';
    c.onclick = () => { trSelDate = c.getAttribute('data-d'); renderTrends(); };
  });
}

function renderTrends() {
  const t = S.trend;
  const box = $('#trendBody');
  if (!t) { box.innerHTML = '<div class="empty-state">加载中…</div>'; return; }

  const real = t.real_tdee;
  let realCard = '';
  if (real) {
    const conf = real.confidence;
    const confColor = conf === '较高' ? 'var(--lime)' : conf === '中等' ? 'var(--orange)' : 'var(--muted)';
    realCard = `
      <div class="card">
        <h3>实测每日消耗 <span class="tag" style="color:${confColor};background:rgba(255,255,255,.06)">置信度 ${conf}</span></h3>
        <div class="kpi"><b>${real.tdee}</b><span>千卡 / 天</span></div>
        <div class="hint">
          用你 ${real.span_days} 天的体重变化反推出来的真实消耗。<br>
          体重 ${real.slope_kg_per_week > 0 ? '增加' : '减少'} ${Math.abs(real.slope_kg_per_week)} kg/周，
          期间平均摄入 ${real.avg_intake} 千卡（覆盖 ${real.coverage}% 的天数）。
        </div>
        <div class="grid2" style="margin-top:14px">
          <div class="mini"><div class="k">目标缺口</div><div class="v">${S.day?.targets.deficit ?? '—'}<small>千卡</small></div></div>
          <div class="mini"><div class="k">相对误差</div><div class="v">${
            S.day ? Math.round(Math.abs(real.tdee - S.day.expenditure) / real.tdee * 100) : '—'}<small>%</small></div></div>
        </div>
        <div style="font-size:11px;color:var(--muted2);margin-top:10px;line-height:1.6">
          这个数字才是不说谎的那个。它把所有估算误差（拍照、克重、手表）全吃掉了。
        </div>
      </div>`;
  } else {
    // 说不清"还差几天"都是废话：直接说清卡在哪一步（数据由 api 的 real_missing 给）
    const miss = t.real_missing || {};
    // 说人话：缺称重就只提称重（体脂秤会自动写进来，这个按钮只是兜底），缺饮食就提记几餐
    const lack = miss.type === 'intake'
      ? `这几天只记了 ${miss.logged} 天饮食，再记 ${Math.max(1, miss.need || 1)} 天就能算出你每天烧多少千卡`
      : `再称一次体重（隔两三天称一次就行），就能算出你每天烧多少千卡`;
    const lackBtn = miss.type === 'intake' ? '记一餐' : '记录体重';
    realCard = `
      <div class="card">
        <h3>实测每日消耗</h3>
        <div class="hint" style="margin-top:0">
          ${lack}。补齐之后就能反推出来。<br>
          <span style="color:var(--muted2);font-size:11px">原理：7700 千卡 ≈ 1kg 脂肪。体重掉的速率，就是你的真实缺口。</span>
        </div>
        <button class="btn sm" id="goWeight" style="margin-top:14px">${lackBtn}</button>
      </div>`;
  }

  // 体重图
  const weights = t.weights || [];
  const lastW = weights.length ? weights[weights.length - 1] : null;
  const selW = trSelDate ? weights.find(x => x.date === trSelDate) : null;
  // 没点过任何点 → 默认当成点了最新的那个点，两行文字和点过时一模一样（不会出现空的「体重 kg」）
  const shownW = selW || lastW;
  const wKgs = weights.map(x => x.kg);
  const wMaxTxt = wKgs.length ? Math.max(...wKgs).toFixed(1) : '—';
  const wMinTxt = wKgs.length ? Math.min(...wKgs).toFixed(1) : '—';
  let wChart = '';
  if (weights.length >= 2) {
    wChart = `<div class="card wchart">
      <h3>体重趋势</h3>
      <div class="wminmax"><span>最高 ${wMaxTxt}</span><span>最低 ${wMinTxt}</span></div>
      <div class="chartwrap" id="trWrap">${lineChart(weights, t.start, t.end, shownW ? shownW.date : null, { range: false })}</div>
      <div class="legend wlegend">
        ${shownW
          ? `<span class="onsel"><i style="background:#6bff9a"></i>${shownW.date.slice(5)} · ${shownW.kg} kg</span>`
          : `<span><i style="background:var(--blue)"></i>体重 kg</span>`}
        <span style="margin-left:auto">${weights.length} 次记录</span>
      </div>
      ${(() => {
        const body = (S.trend && S.trend.body) || {};
        const datesB = Object.keys(body).sort();
        const latestB = datesB.length ? datesB[datesB.length - 1] : null;
        // 图上点了哪天，体脂秤那行就跟哪天走；那天没有体脂秤记录就退回最新一条
        const pickD = (trSelDate && body[trSelDate]) ? trSelDate : latestB;
        const b = pickD ? body[pickD] : null;
        if (!b || (!b.bf && !b.bmi)) return '';
        const bits = [];
        if (b.bf) bits.push('体脂率 ' + b.bf + '%');
        if (b.bmi) bits.push('BMI ' + b.bmi);
        // 上面那行已经有日期和体重时，这行就不重复写日期，只留数值
        const needDate = !shownW || pickD !== shownW.date;
        return `<div class="hint wbody">${needDate ? pickD.slice(5) + ' · ' : ''}${bits.join(' · ')}</div>`;
      })()}
    </div>`;
  } else {
    wChart = `<div class="card">
      <h3>体重趋势</h3>
      <div class="empty-state" style="padding:16px 0">至少记录 2 次体重才能画图<br>
      <button class="btn sm" id="goWeight2" style="max-width:180px;margin:14px auto 0">记录体重</button></div>
    </div>`;
  }

  // 平衡柱状图
  const bars = t.series.map(s => ({
    date: s.date,
    v: s.balance,
    intake: s.intake,
  }));
  const hasSurplus = bars.some(b => b.v != null && b.v < 0);
  const maxAbs = Math.max(300, ...bars.map(b => Math.abs(b.v || 0)));
  const barHtml = bars.map(b => {
    if (b.v == null) return `<div class="barcol"></div>`;
    if (!hasSurplus) {
      // 全是缺口时，从底部往上长，不浪费一半空间
      const h = b.v / maxAbs * 100;
      return `<div class="barcol" title="${b.date} 缺口 ${b.v}">
        <i style="height:${Math.max(1.5, h)}%;bottom:0;background:var(--lime);opacity:.85"></i>
      </div>`;
    }
    const h = Math.abs(b.v) / maxAbs * 50;
    const up = b.v > 0;
    return `<div class="barcol" title="${b.date} ${b.v}">
      <i style="height:${Math.max(1.5, h)}%;${up ? 'bottom:50%' : 'top:50%'};background:${up ? 'var(--lime)' : 'var(--orange)'};opacity:.85"></i>
    </div>`;
  }).join('');

  const topBox = $('#trendTop');
  if (topBox) topBox.innerHTML = realCard;   // 状态卡（实测消耗）不受 7/30/90 影响，单独放上面
  box.innerHTML = `
    ${t.logged_days === 0 ? `
    <div class="card">
      <h3>每日热量平衡</h3>
      <div class="empty-state" style="padding:26px 0">
        还没有数据<br>
        <span style="font-size:11.5px">去「今日」记第一笔，这里就会说话</span>
      </div>
    </div>` : `
    <div class="card">
      <h3>每日热量平衡 <span class="tag" id="avgTag">${t.avg_balance != null ? (t.avg_balance >= 0 ? '平均缺口 ' + t.avg_balance : '平均盈余 ' + Math.abs(t.avg_balance)) : '暂无数据'}</span></h3>
      <div class="barchart ${hasSurplus ? '' : 'bottom'}">${barHtml}</div>
      <div class="legend">
        <span><i style="background:var(--lime)"></i>缺口</span>
        <span><i style="background:var(--orange)"></i>盈余</span>
        <span style="margin-left:auto">${t.logged_days} / ${t.days} 天有记录</span>
      </div>
    </div>`}
    ${wChart}
    <div class="card">
      <h3>区间统计</h3>
      <div class="grid2">
        <div class="mini"><div class="k">平均摄入</div><div class="v">${t.avg_intake || '—'}<small>千卡</small></div></div>
        <div class="mini"><div class="k">平均消耗</div><div class="v">${t.avg_expenditure || '—'}<small>千卡</small></div></div>
        <div class="mini"><div class="k">记录天数</div><div class="v">${t.logged_days}<small>/ ${t.days}</small></div></div>
        <div class="mini"><div class="k">体重变化</div><div class="v">${
          weights.length >= 2
            ? ((weights[weights.length - 1].kg - weights[0].kg) >= 0 ? '+' : '') +
              (weights[weights.length - 1].kg - weights[0].kg).toFixed(1) + '<small>kg</small>'
            : '—'}</div></div>
      </div>
    </div>`;

  const gw = $('#goWeight') || $('#goWeight2');
  if (gw) {
    // 缺的是饮食记录就开到「记一餐」，缺的是体重就开体重弹层
    const needFood = gw.textContent.trim() !== '记录今天的体重' && gw.textContent.trim() !== '记录体重';
    gw.onclick = () => (needFood ? openAdd() : openWeight());
  }
  wireTrendChart();
}

function lineChart(points, start, end, selDate, opts = {}) {
  const showRange = opts.range !== false;   // 趋势页把「最高/最低」放到卡片标题右边，就不在图上重复画
  const W = 320, H = 130, pl = 4, pr = 4, pt = 12, pb = 22;
  const xs = points.map(p => +parseISO(p.date));
  const ys = points.map(p => p.kg);
  let min = Math.min(...ys), max = Math.max(...ys);
  if (max - min < 1.2) { const m = (max + min) / 2; min = m - 0.6; max = m + 0.6; }
  const padY = (max - min) * 0.18;
  min -= padY; max += padY;
  // 横轴按传入的 start/end 铺满（这样 7 天窗口里只有 2 个点也不会挤在边上）
  const sd = parseISO(start), ed = parseISO(end);
  const x0 = Number.isFinite(sd) ? sd : Math.min(...xs);
  const x1 = Number.isFinite(ed) ? ed : Math.max(...xs);
  const X = v => pl + (W - pl - pr) * (x1 === x0 ? 0.5 : (v - x0) / (x1 - x0));
  const Y = v => pt + (H - pt - pb) * (1 - (v - min) / (max - min));

  const path = points.map((p, i) => `${i ? 'L' : 'M'}${X(xs[i]).toFixed(1)},${Y(p.kg).toFixed(1)}`).join(' ');
  const area = `${path} L${X(xs[xs.length - 1]).toFixed(1)},${H - pb} L${X(xs[0]).toFixed(1)},${H - pb} Z`;
  const dots = points.map((p, i) => {
    const last = i === points.length - 1;
    const sel = selDate && p.date === selDate;
    const r = sel ? 5.5 : (last ? 4.5 : 4);
    const fill = sel ? '#6bff9a' : (last ? '#d6ff4b' : '#6ea8ff');
    return `<circle data-d="${p.date}" cx="${X(xs[i]).toFixed(1)}" cy="${Y(p.kg).toFixed(1)}" r="${r}" fill="${fill}" stroke="#15181b" stroke-width="1.5" style="pointer-events:all"/>`;
  }).join('');
  // 选中点：一条竖线从图顶到点的位置
  let vline = '';
  if (selDate) {
    const si = points.findIndex(p => p.date === selDate);
    if (si >= 0) {
      const vx = X(xs[si]).toFixed(1), vy = Y(points[si].kg).toFixed(1);
      vline = `<line x1="${vx}" y1="${pt}" x2="${vx}" y2="${H - pb}" stroke="rgba(214,255,75,.55)" stroke-width="1" stroke-dasharray="3 3"/>`;
    }
  }

  const first = points[0], last = points[points.length - 1];
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet">
    <defs><linearGradient id="wg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#6ea8ff" stop-opacity=".22"/>
      <stop offset="100%" stop-color="#6ea8ff" stop-opacity="0"/>
    </linearGradient></defs>
    <path d="${area}" fill="url(#wg)"/>
    ${vline}
    <path d="${path}" fill="none" stroke="#6ea8ff" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>
    ${dots}
    <text x="${pl}" y="${H - 6}" style="font-size:9px">${first.date.slice(5)}</text>
    <text x="${W - pr}" y="${H - 6}" text-anchor="end" style="font-size:9px">${last.date.slice(5)}</text>
    ${showRange ? `<text x="${W - pr}" y="11" text-anchor="end" style="font-size:9px;fill:var(--muted);stroke:#15181b;stroke-width:2.6;paint-order:stroke">最高 ${Math.max(...ys).toFixed(1)}</text>
    <text x="${W - pr}" y="22" text-anchor="end" style="font-size:9px;fill:var(--muted);stroke:#15181b;stroke-width:2.6;paint-order:stroke">最低 ${Math.min(...ys).toFixed(1)}</text>` : ''}
  </svg>`;
}

/* ---------------- 主题 ---------------- */
// 目标模式：只决定「蛋白质系数 + 脂肪占比」，不动用户设的缺口/盈余
// 目标模式：蛋白质系数 + 脂肪占比 + 建议缺口（正=缺口，负=盈余）
const DIET_MODES = {
  cut:      { n: '减脂', p: 2.0, fat: 0.25, deficit: 300,  tip: '缺口 300 · 蛋白 2.0' },
  maintain: { n: '维持', p: 1.6, fat: 0.28, deficit: 0,    tip: '不缺口 · 蛋白 1.6' },
  bulk:     { n: '增肌', p: 1.8, fat: 0.25, deficit: -250, tip: '盈余 250 · 蛋白 1.8' },
};
const THEMES = { lime: '#d6ff4b', blue: '#6ea8ff', orange: '#ff9f45' };

// 目标模式下面那行「建议」：只写具体数值，不重复模式名（上面的卡牌已经说清了）
function modeHintHTML(k) {
  const mm = DIET_MODES[k] || DIET_MODES.maintain;
  const d = Number(mm.deficit) || 0;
  const head = d > 0 ? '建议缺口 <b>' + d + ' 千卡 / 天</b>'
             : d < 0 ? '建议盈余 <b>' + (-d) + ' 千卡 / 天</b>'
             : '建议<b>不设缺口</b>（收支平衡）';
  const tail = d > 0 ? '，即比消耗少吃 ' + d + ' 千卡'
             : d < 0 ? '，即比消耗多吃 ' + (-d) + ' 千卡' : '';
  return head + tail + '；蛋白 <b>' + mm.p.toFixed(1) + ' g/kg</b>、脂肪约 <b>' + Math.round(mm.fat * 100) + '%</b> 热量';
}

// 缺口/盈余合理性提示：只提醒，绝不改用户填的数
function deficitAdvice(exp, deficit, bmr) {
  const d = Number(deficit) || 0;
  const e = Number(exp) || 0;
  const abs = Math.abs(d);
  if (!e) return null;
  const pct = Math.round(abs / e * 100);
  const safe = Math.round(Math.min(e * 0.25, 500));
  if (d > 0) {                                    // 缺口
    if (d >= e) return { lv: 'hard', t: `缺口 ${d} 已超过当天消耗 ${e}，每日可吃会变成 0。建议不超过 ${safe}（消耗的 25%）。` };
    if (bmr && e - d < bmr * 0.75) return { lv: 'hard', t: `每日可吃只剩 ${e - d}，已低于基础代谢 ${bmr} 的 75%，长期会掉肌肉、代谢变慢。建议缺口不超过 ${safe}。` };
    if (abs > 500 || pct > 25) return { lv: 'warn', t: `缺口偏大（占消耗 ${pct}%，约 ${(abs * 7 / 7700).toFixed(2)} kg/周）。一般建议不超过 ${safe}（25%），减得稳、不易反弹。` };
    return null;
  }
  if (d < 0) {                                    // 盈余
    if (abs > 700) return { lv: 'hard', t: `盈余 ${abs} 偏大，多出的热量更容易变成脂肪。增肌一般建议 200–300。` };
    if (abs > 400) return { lv: 'warn', t: `盈余 ${abs}（约 ${(abs * 7 / 7700).toFixed(2)} kg/周），多数人 200–300 已经够用。` };
    return null;
  }
  return null;
}
// 每个主题的[主光色, 副光色]，背景光晕和点阵跟着变
const GLOWS = {
  lime: ['#d6ff4b', '#46ffc4'],
  blue: ['#6ea8ff', '#8be3ff'],
  orange: ['#ff9f45', '#ffd08a'],
};
const rgbOf = hex => {
  const h = hex.replace('#', '');
  return [parseInt(h.slice(0,2),16), parseInt(h.slice(2,4),16), parseInt(h.slice(4,6),16)].join(', ');
};
const THEME_NAMES = { lime: '荧光绿', blue: '海水蓝', orange: '活力橙' };
function applyTheme(name) {
  const c = THEMES[name] || THEMES.lime;
  const g = GLOWS[name] || GLOWS.lime;
  const root = document.documentElement.style;
  root.setProperty('--lime', c);
  root.setProperty('--glow-rgb', rgbOf(g[0]));
  root.setProperty('--glow2-rgb', rgbOf(g[1]));
}


/* 左边缘往右滑 = 返回（关卡片 / 关弹层 / 退出我的子页） */
function goBack() {
  const on = id => { const el = $(id); return el && el.classList.contains('on'); };
  if (on('#grpSheet')) return closeGroup();
  if (on('#addSheet')) return closeAdd();
  if (on('#helpSheet')) return closeHelp();
  if (on('#weightSheet')) return closeWeight();
  if (mePage) {
    const v = $('#view-me');
    if (v) v.classList.add('slideout');
    setTimeout(() => {
      mePage = null;
      if (v) v.classList.remove('slideout');
      renderMe();
    }, 170);
  }
}

