/* ---------------- 快捷指令自动同步 ---------------- */

/**
 * iOS 快捷指令可以每天自动读取健康数据，然后打开形如
 *   ?watch=1&a=480&r=1580&s=9200
 * 的链接。这里把它接住，写进当天记录，再把参数从地址栏抹掉。
 */
function consumeHealthLink() {
  try {
    const u = new URL(location.href);
    if (!u.searchParams.has('watch')) return null;
    const g = k => {
      const v = u.searchParams.get(k);
      return (v === null || v === '') ? null : Number(v);
    };
    const active = g('a'), resting = g('r'), total = g('t'), steps = g('s');
    if (active === null && resting === null && total === null) return null;
    const date = u.searchParams.get('d') || todayISO();
    const d = Store.load();
    d.daily[date] = { active, resting, total, steps, source: 'shortcut' };
    Store.save();
    history.replaceState(null, '', u.pathname + u.hash);
    return date;
  } catch (e) {
    return null;
  }
}

/**
 * 体脂秤链接：快捷指令从「健康」读出体重/体脂率/BMI 后打开
 *   ?body=1&w=65.9&bf=16.9&bmi=21.8&ffm=51.9&d=2026-10-18
 * 写进当天体重 + 身体成分，再把参数抹掉
 */
function consumeBodyLink() {
  try {
    const u = new URL(location.href);
    if (!u.searchParams.has('body')) return null;
    const g = k => {
      const v = u.searchParams.get(k);
      return (v === null || v === '') ? null : Number(v);
    };
    const w = g('w'), bf = g('bf'), bmi = g('bmi'), ffm = g('ffm');
    if (w === null && bf === null) return null;
    const date = u.searchParams.get('d') || todayISO();
    const d = Store.load();
    if (w !== null) { d.weights[date] = w; d.profile.weight_kg = w; }
    // BMI 没传就自己算（身高在「身体与目标」里）
    let bmiVal = bmi;
    if (!bmiVal && w) {
      const h = Number(d.profile.height_cm) || 0;
      if (h > 0) bmiVal = Math.round((w / Math.pow(h / 100, 2)) * 10) / 10;
    }
    d.body = d.body || {};
    d.body[date] = { bf, bmi: bmiVal, ffm };
    Store.save();
    history.replaceState(null, '', u.pathname + u.hash);
    return date;
  } catch (e) { return null; }
}

/* ---- 体脂秤：快捷指令把 {d,w,bf} 写进仓库的 body.json，这里拉下来 ---- */
// 单位归一：快捷指令可能返回「克」(66000) 或「小数」(0.169)，统一成 kg / %
function normKg(v) {
  const n = Number(v) || 0;
  if (!n) return 0;
  return n >= 300 ? Math.round(n / 100) / 10 : Math.round(n * 10) / 10;
}
function normPct(v) {
  const n = Number(v) || 0;
  if (!n) return 0;
  return n > 0 && n <= 1 ? Math.round(n * 1000) / 10 : Math.round(n * 10) / 10;
}

async function pullBodyHistory() {
  try {
    let txt = '';
    try { const r0 = await fetchT('body-history.json?t=' + Date.now(), { cache: 'no-store' }, 4000); if (r0.ok) txt = await r0.text(); } catch (e) {}
    if (!txt) txt = await giteeGetText('body-history.json');
    const j = JSON.parse(txt);
    const items = Array.isArray(j && j.items) ? j.items : [];
    if (!items.length) { logError('err-history', '身体历史读取失败', 'body-history.json 是空的或格式不对'); return 0; }
    const d = Store.load();
    d.body = d.body || {}; d.weights = d.weights || {};
    let n = 0;
    for (const it of items) {
      const dd = String(it.d || '').slice(0, 10);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(dd)) continue;
      const w = normKg(it.w), bf = normPct(it.bf);
      const bmi = Number(it.bmi) || null, ffm = normKg(it.ffm) || null;
      if (!w && !bf && !bmi && !ffm) continue;
      if (w) d.weights[dd] = w;
      d.body[dd] = { bf: bf || null, bmi, ffm };
      n++;
    }
    if (!n) return 0;
    const lastD = Object.keys(d.body).sort().pop();
    if (lastD && d.weights[lastD]) d.profile.weight_kg = d.weights[lastD];
    Store.save({ silent: true });
    return n;
  } catch (e) { return 0; }
}

async function pullBodyJson(forceFresh) {
  try {
    const needFresh = !!forceFresh || Date.now() - freshAt.body > 300000;
    if (needFresh) freshAt.body = Date.now();
    const stamp = Date.now();
    const jobs = [getText('body.json?t=' + stamp), getText(GH_RAW + 'body.json?t=' + stamp)];
    jobs.push((needFresh || giteeBlockedUntil < Date.now()) ? giteeFresh('body.json') : Promise.resolve(''));
    const got = await Promise.all(jobs);
    const dOf = t => { try { const j = JSON.parse(t); return String((j && j.d) || '').slice(0, 10); } catch (e) { return ''; } };
    let bodyText = '', bestD = '';
    got.forEach(t => {
      if (!t) return;
      const dd = dOf(t);
      if (dd >= bestD) { bestD = dd; bodyText = t; }   // 日期更新的那份优先
    });
    if (!bodyText) { logError('err-body', '体脂数据读取失败', 'body.json 三路都没读到'); return false; }
    // 用文件的 Last-Modified 当作「这份数据是什么时候写上去的」
    let bodyAt = '';
    try {
      const lm = (typeof r !== 'undefined' && r && r.headers) ? r.headers.get('last-modified') : '';
      if (lm) {
        const dt = new Date(lm);
        const p2 = n => String(n).padStart(2, '0');
        bodyAt = `${dt.getMonth() + 1}-${p2(dt.getDate())} ${p2(dt.getHours())}:${p2(dt.getMinutes())}`;
      }
    } catch (e) {}
    let j;
    try { j = JSON.parse(bodyText); } catch (e) {
      // 快捷指令可能写成 {"w":"66\n65.9"} 这种换行没转义的非法 JSON，先修一下
      try { j = JSON.parse(bodyText.replace(/\r?\n/g, '\\n')); } catch (e2) { return null; }
    }
    if (!j) return null;
    if (bodyAt) j._at = bodyAt;   // 这份数据写上去的时间
    // 支持历史批量导入：{"items":[{"d","w","bf","bmi","ffm"}, ...]}
    if (Array.isArray(j.items)) {
      const d0 = Store.load();
      d0.body = d0.body || {}; d0.weights = d0.weights || {};
      let n = 0;
      for (const it of j.items) {
        const dd = String(it.d || '').slice(0, 10);
        if (!/^\d{4}-\d{2}-\d{2}$/.test(dd)) continue;
        const w = Number(it.w) || 0, bf = Number(it.bf) || 0;
        const bmi = Number(it.bmi) || null, ffm = Number(it.ffm) || null;
        if (!w && !bf && !bmi && !ffm) continue;
        if (w) d0.weights[dd] = w;
        d0.body[dd] = { bf: bf || null, bmi, ffm };
        n++;
      }
      if (!n) return null;
      const lastD = Object.keys(d0.body).sort().pop();
      if (lastD && d0.weights[lastD]) d0.profile.weight_kg = d0.weights[lastD];
      Store.save({ silent: true });
      return { d: lastD, n };
    }
    // 快捷指令可能一次返回多条样本（"66\n65.9"），取最后一条（最新）
    const pick = v => {
      const lines = String(v == null ? '' : v).split(/\r?\n/).map(x => x.trim()).filter(Boolean);
      return lines.length ? Number(lines[lines.length - 1]) || 0 : 0;
    };
    const w = normKg(pick(j.w)), bf = normPct(pick(j.bf)), jbmi = pick(j.bmi), jffm = normKg(pick(j.ffm));
    if (!w && !bf && !jbmi && !jffm) return null;
    // 数值校验：明显不合理的数据不写进来
    if (w && (w < 25 || w > 300)) {
      logError('err-body', '体重数值异常', `E10 读到 ${w} kg，不合常理，已忽略`);
      return null;
    }
    if (bf && (bf <= 1 || bf >= 70)) {
      logError('err-body', '体脂数值异常', `E10 读到 ${bf}%，不合常理，已忽略`);
      return null;
    }
    const d = Store.load();
    d.body = d.body || {}; d.weights = d.weights || {};
    const explicit = (String(j.d || '').match(/\d{4}-\d{2}-\d{2}/) || [])[0];
    let date = explicit;
    if (!date) {
      // 快捷指令没给日期：如果这次的数值和「最近一次」完全一样，说明没有新称重 —— 不新增日期
      const latestD = Object.keys(d.body).concat(Object.keys(d.weights)).sort().pop();
      const lb = latestD ? (d.body[latestD] || {}) : {};
      const same = latestD
        && Number(d.weights[latestD] || 0) === Number(w || 0)
        && Number(lb.bf || 0) === Number(bf || 0)
        && Number(lb.bmi || 0) === Number(jbmi || 0)
        && Number(lb.ffm || 0) === Number(jffm || 0);
      if (same) return { d: latestD, n: 0, same: true };
      date = todayISO();
    }
    const cur = (d.body && d.body[date]) || {};
    if (d.weights[date] === w && cur.bf === bf) return j;
    if (w) { d.weights[date] = w; d.profile.weight_kg = w; }
    let bmi = jbmi || cur.bmi || null;
    if (!bmi && w) {
      const h = Number(d.profile.height_cm) || 0;
      if (h > 0) bmi = Math.round((w / Math.pow(h / 100, 2)) * 10) / 10;
    }
    const ffm = jffm || cur.ffm || null;   // 去脂体重（秤上给的）
    d.body = d.body || {};
    d.body[date] = { bf: bf || cur.bf || null, bmi, ffm };
    Store.save({ silent: true });   // 不参与「谁更新」判定，避免两台设备互相盖掉记录
    return j;
  } catch (e) { return null; }
}

/* ---------------- 云端同步（GitHub 上的 health.json） ---------------- */

/**
 * 快捷指令每天把「日期|活动能量」写进仓库根目录的 health.json。
 * 这里在打开 App 时拉一次，写进当天记录。
 * 日期可能是「2026-10-18」「2026/10/18」「2026年10月18日 22:09」等，
 * 统一宽松解析；实在解析不出来就当作今天。
 */
function parseLooseDate(s) {
  const m = String(s || '').match(/(\d{4})\D(\d{1,2})\D(\d{1,2})/);
  if (m) {
    return `${m[1]}-${String(m[2]).padStart(2, '0')}-${String(m[3]).padStart(2, '0')}`;
  }
  const d = new Date(s);
  if (!isNaN(d.getTime())) return isoOf(d);
  return null;
}

/* 最近一次从 health.json 读到的内容，给刷新提示用 */
let lastCloud = null;

/* 每次打开 App 的头一次拉取：直接读 Gitee 源文件，不等 15 分钟一次的镜像同步。
   之后的轮询再走同源镜像（快、不限流）。手动刷新也强制读源。 */
async function giteeFresh(path) {
  try { const t = await giteeGetText(path, true); return String(t || '').trim(); } catch (e) { return ''; }
}

/* 三路同时取：Gitee 源 / GitHub raw / 同源镜像，谁的内容时间最新就用谁。
   这样任何一路挂了（Gitee 限流、镜像任务漏跑、Pages 缓存）都不会把数据卡住。 */
const GH_RAW = 'https://raw.githubusercontent.com/karenwang0013/calorie-ledger/main/';
function healthStamp(t) {
  const m = String(t || '').match(/(\d{4})\D+(\d{1,2})\D+(\d{1,2})\D+(\d{1,2}):(\d{2})/);
  return m ? new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]).getTime() : 0;
}
async function getText(url) {
  try { const r = await fetchT(url, { cache: 'no-store' }, 4000); if (r.ok) return (await r.text()).trim(); } catch (e) {}
  return '';
}
async function fetchHealthText(forceFresh) {
  const needFresh = !!forceFresh || Date.now() - freshAt.health > 300000;
  if (needFresh) freshAt.health = Date.now();
  const stamp = Date.now();
  const jobs = [getText('health.json?t=' + stamp), getText(GH_RAW + 'health.json?t=' + stamp)];
  if (needFresh || giteeBlockedUntil < Date.now()) jobs.push(giteeFresh('health.json'));
  else jobs.push(Promise.resolve(''));
  const got = await Promise.all(jobs);
  let best = '', bestTs = -1, from = '';
  got.forEach((t, i) => {
    if (!t) return;
    const ts = healthStamp(t);
    if (ts > bestTs) { bestTs = ts; best = t; from = ['镜像', 'GitHub', 'Gitee'][i] || ''; }
  });
  if (best) { lastHealthFrom = from; return best; }
  logError('err-health', '热量数据读取失败', '三路都没读到 health.json');
  return '';
}

async function pullCloudData(forceFresh) {
  try {
    const txt = await fetchHealthText(forceFresh);
    if (!txt) return null;
    const sep = txt.includes('|') ? '|' : ',';
    const i = txt.lastIndexOf(sep);
    if (i < 0) return null;
    const head = txt.slice(0, i).trim();
    // 值可能是单个数字，也可能是多行/多列的数值列表，全部加起来
    const tail = String(txt.slice(i + 1)).replace(/(\d),(\d)/g, '$1$2');
    const nums = tail.match(/\d+(?:\.\d+)?/g) || [];
    const active = Math.round(nums.reduce((s, n) => s + Number(n), 0));
    if (!active || active <= 0) { logError('err-health', '热量数据读取失败', 'health.json 里没有有效的活动消耗'); return null; }
    if (active < 5 || active > 5000) {
      logError('err-health', '热量数值异常', `E10 读到 ${active} 千卡，不合常理，已忽略`);
      return null;
    }
    const date = parseLooseDate(head) || todayISO();
    // 快捷指令写进去的时刻，用来告诉用户「这份数据是什么时候的」
    const tm = head.match(/(\d{1,2}):(\d{2})/);
    const at = tm ? `${date} ${String(tm[1]).padStart(2, '0')}:${tm[2]}` : date;
    const d = Store.load();
    const cur = d.daily[date] || {};
    const unchanged = cur.active === active && cur.source === 'cloud';
    d.daily[date] = Object.assign({}, cur, { active, source: 'cloud', cloudAt: at });
    if (!unchanged || cur.cloudAt !== at) Store.save();
    try { clearErr('err-health'); } catch (e) {}
    lastCloud = { date, active, at, changed: !unchanged };
    return unchanged ? null : date;
  } catch (e) {
    return null;
  }
}

/* ---------------- 启动兜底：出错不白屏 ---------------- */
function showBootError(msg) {
  try {
    const el = document.getElementById('bootErr');
    if (!el) return;
    el.style.display = 'block';
    el.querySelector('.be-msg').textContent = String(msg || '未知错误').slice(0, 200);
  } catch (e) {}
}
window.addEventListener('error', (e) => showBootError(e.message));
window.addEventListener('unhandledrejection', (e) => showBootError((e.reason && e.reason.message) || e.reason));

/* ---------------- 初始化 ---------------- */
/* ---------------- Dock 液态滑块 ---------------- */
/* 平时停在当前 Tab 上；按下任意按钮，滑块会滑过去并在按下的位置亮一团光，松手弹回 */
function initDockLens() {
  const inner = document.querySelector('.tabbar .inner');
  const lens = inner && inner.querySelector('.dock-lens');
  if (!inner || !lens) return;

  const activeTab = () => inner.querySelector('.tab.on');
  let evX = 0, evY = 0;

  const place = (el, opt = {}) => {
    if (!el) return;
    const cs = getComputedStyle(inner);
    const ir = inner.getBoundingClientRect();
    const r = el.getBoundingClientRect();
    // 滑块 = Dock 里的一整格：按网格列宽算，左中右三格一样宽，图标在格子正中
    const cols = (cs.gridTemplateColumns || '').split(' ').map(v => parseFloat(v) || 0).filter(Boolean);
    const gap = parseFloat(cs.columnGap) || 0;
    const items = [...inner.querySelectorAll('.tab, .fab')];
    const idx = Math.max(0, items.indexOf(el));
    const padL = parseFloat(cs.paddingLeft) || 0;
    const before = cols.slice(0, idx).reduce((a, b) => a + b, 0) + gap * idx;
    const cellW = cols[idx] || r.width;
    // 滑块到 Dock 边的留白：上下左右必须是**同一个数**，
    // 这样"圆角同心"才能成立（内圆半径 = Dock 圆角 − 这个留白，弧线才是平行的）
    const PAD = 10;
    // 注意：Dock 外框有 1px 边框，高度要按**边框里面**那块算，
    // 否则会变成"上面 8px、下面 6px"（之前就是这样，看着上面宽一点）
    const w = Math.max(70, Math.round(cellW + 2 * (padL - PAD)));
    const bT = parseFloat(cs.borderTopWidth) || 0;
    const bB = parseFloat(cs.borderBottomWidth) || 0;
    const visH = ir.height - bT - bB;
    const h = Math.max(40, Math.round(visH - PAD * 2));
    const cellLeft = padL + before;
    lens.style.setProperty('--lens-w', w + 'px');
    lens.style.setProperty('--lens-h', h + 'px');
    lens.style.setProperty('--lens-x', Math.round(cellLeft + (cellW - w) / 2) + 'px');
    lens.style.setProperty('--lens-y', Math.round((visH - h) / 2) + 'px');
    // 圆角同心：内圆 = Dock 圆角 − 留白（不是"按比例缩"，那样弧线对不上）
    // Dock 圆角是画在边框外沿的，所以先减掉那 1px 边框，再减留白 —— 这样两条弧线才是严格平行
    const dockR = parseFloat(cs.borderTopLeftRadius) || 26;
    lens.style.setProperty('--lens-r', Math.max(12, Math.round(dockR - PAD - bT)) + 'px');
    if (opt.press) {
      const hx = (evX - r.left) / Math.max(1, r.width) * 100;
      const hy = (evY - r.top) / Math.max(1, r.height) * 100;
      lens.style.setProperty('--hx', Math.max(0, Math.min(100, hx)).toFixed(1) + '%');
      lens.style.setProperty('--hy', Math.max(0, Math.min(100, hy)).toFixed(1) + '%');
    }
    lens.classList.add('on');
  };

  const fabEl = inner.querySelector('.fab');
  let target = null;                       // 滑块现在停在哪
  const lit = el => {
    inner.querySelectorAll('.lit').forEach(x => x.classList.remove('lit'));
    if (el) el.classList.add('lit');      // 停在哪，哪个就亮
  };
  // 停稳（不再滑动、不是按住）→ 换成实色块；一开始就是实色，不要闪一下玻璃
  const settle = (delay) => {
    lens.classList.remove('settled');
    clearTimeout(lens.__settleT);
    lens.__settleT = setTimeout(() => {
      lens.classList.add('fadein');
      void lens.offsetWidth;
      lens.classList.add('settled');
      setTimeout(() => lens.classList.remove('fadein'), 2400);
    }, delay);
  };
  const go = el => { if (!el) return; target = el; place(el); lit(el); settle(520); };
  const reflow = () => { lens.classList.remove('press'); place(target || fabEl); settle(520); };
  window.__dockLens = { go, reflow };

  inner.addEventListener('pointerdown', ev => {
    const el = ev.target.closest('.tab, .fab');
    if (!el) return;
    evX = ev.clientX; evY = ev.clientY;
    target = el;                  // 按下去就认这一格，松手不会跳回原来那格
    lens.classList.add('fadeout');      // 按住时是玻璃，不是实色（0.25 秒回玻璃）
    lens.classList.remove('settled', 'fadein');
    setTimeout(() => lens.classList.remove('fadeout'), 320);
    place(el, { press: true });
    lit(el);
    lens.classList.add('press');
    if (el.classList.contains('fab')) el.classList.add('pressed');
  }, { passive: true });

  const release = () => {
    inner.querySelectorAll('.fab.pressed').forEach(f => f.classList.remove('pressed'));
    if (!lens.classList.contains('press')) return;
    lens.classList.remove('press');
    // 松手后滑回当前选中的 Tab（点 Tab 的话此时已经切过去了，看起来就是原地弹一下）
    setTimeout(() => { if (!lens.classList.contains('press')) reflow(); }, 10);
  };
  window.addEventListener('pointerup', release, { passive: true });
  window.addEventListener('pointercancel', release, { passive: true });

  // 打开 App 时滑块直接落在当前选中的 Tab 上（不播放入场动画），之后跟着点击跑
  lens.classList.add('noanim');
  requestAnimationFrame(() => requestAnimationFrame(() => {
    go(activeTab() || fabEl);
    lens.classList.add('settled');       // 首帧就是实色，不播玻璃→实色的闪变
    requestAnimationFrame(() => lens.classList.remove('noanim'));
  }));
  // 转屏 / 尺寸变化时重新贴一次（尺寸和位置会变）
  window.addEventListener('resize', () => setTimeout(reflow, 120));
  window.addEventListener('orientationchange', () => setTimeout(reflow, 260));
}

function init() {
  if (window.__inited) return;      // 脚本被补加载时可能被调用两次，只跑一次
  window.__inited = true;
  const synced = consumeHealthLink();
  try { initDockLens(); } catch (e) { console.warn('dock lens', e); }   // 液态滑块出问题也不许拖住整个 App
  wireAddDrag();   // 记录卡片：下滑关闭
  $$('.tab').forEach(b => b.onclick = () => switchView(b.dataset.view));
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('sw.js').catch(() => {});
    // 新 Service Worker 接管时**不要自动刷新页面**：
    // 刚点过"强制更新"时这页本来就是最新下载的，再刷一次就是白刷（表现为"刷一遍又刷一遍、参数先没了又回来"）；
    // 真出了新版本，由 checkVersion 比对 version.txt 负责刷一次。
    navigator.serviceWorker.addEventListener('controllerchange', () => {});
  }
  $('#prevDay').onclick = () => { S.date = addDays(S.date, -1); loadDay(); };
  $('#nextDay').onclick = () => {
    if (S.date >= S.today) return;
    S.date = addDays(S.date, 1);
    loadDay();
  };
  $('#fab').onclick = () => openAdd();
  $('#addTop').onclick = () => openAdd();
  const addCloseBtn = $('#addClose');
  if (addCloseBtn) addCloseBtn.onclick = closeAdd;   // 记录卡片不再有右上角叉号（靠下滑或点空白关闭）
  $('#addMask').onclick = closeAdd;

  $$('#addTabs button').forEach(b => b.onclick = () => setAddMode(b.dataset.m));
  $('#photo2Cam').onchange = e => { handlePick(e.target.files[0]); e.target.value = ''; };
  $('#photo2Alb').onchange = e => { handlePick(e.target.files[0]); e.target.value = ''; };
  $('#del2').onclick = ev => {
    ev.stopPropagation();
    if (S.photo2URL) { URL.revokeObjectURL(S.photo2URL); S.photo2URL = null; }
    S.photo2Data = null;
    $('#pv2').removeAttribute('src');
    $('#pv2').hidden = true;
    $('#del2').hidden = true;
    $('#emptyB').hidden = false;
    saveDraft();
  };

  // 点两个照片框本身也能调起系统相册
  let pickTarget = 0;
  const pickFor = slot => { pickTarget = slot; $('#photoAlbum').click(); };
  $$('.pslot').forEach(el => el.onclick = ev => {
    if (ev.target.closest('[data-del]') || ev.target.closest('.shotdel')) return;
    pickFor(Number(el.dataset.slot) || 0);
  });
  $('#photoAlbum').onchange = e => {
    const f = e.target.files[0];
    e.target.value = '';
    if (!f) return;
    if (pickTarget === 2) handlePhoto2(f); else handlePhoto(f);
    pickTarget = 0;
  };

  const pickCam = () => $('#photoInput').click();
  const pickAlb = () => $('#photoAlbum').click();
  $('#pickCamera').onclick = ev => { ev.stopPropagation(); pickCam(); };
  $('#pickAlbum').onclick = ev => { ev.stopPropagation(); pickAlb(); };
  $('#photoDel').onclick = ev => { ev.stopPropagation(); resetPhotoUI(); saveDraft(); };
  $('#photoInput').onchange = e => { handlePick(e.target.files[0]); e.target.value = ''; };
  $('#photoGo').onclick = runPhoto;
  $('#textGo').onclick = runText;
  $('#saveItems').onclick = saveItems;
  $('#nutMask').onclick = closeNutEdit;
  // 下滑关闭（拖拽结束时一定会复位，touchcancel 也复位）；叉号和点遮罩也都能关
  wireSheetDrag($('#nutSheet'), $('#nutSheet .sh-body'), closeNutEdit);
  const ut = $('#nutUnitTog');
  if (ut) ut.onclick = ev => { ev.preventDefault(); setNutUnit(nutUnit === 'kJ' ? 'kcal' : 'kJ', true); };
  // 改克数：把"这一份"的四项按每 100 克等比换算（12.5 → 25 克，数值翻倍；反过来减半）。
  // 只动用户还没手改过的格子，手填过的保持原样（避免覆盖刚输入的数）。
  const refEl = $('#nutRef');
  if (refEl) refEl.oninput = () => {
    const ref = Number(refEl.value) || 0;
    const share = ref / 100;
    if (ref > 0) {
      const put = (sel, v) => { const el = $(sel); if (el) el.value = v; };
      if (!nutDirty.k) put('#nutKcal', Math.round(nutUnit === 'kJ' ? nutBase.k * share * KJ_PER_KCAL : nutBase.k * share));
      if (!nutDirty.p) put('#nutP', +((nutBase.p * share).toFixed(1)));
      if (!nutDirty.c) put('#nutC', +((nutBase.c * share).toFixed(1)));
      if (!nutDirty.f) put('#nutF', +((nutBase.f * share).toFixed(1)));
    }
    paintNutPreview();
  };
  const kEl = $('#nutKcal');
  if (kEl) kEl.oninput = () => { nutDirty.k = true; paintNutPreview(); };
  ['#nutP', '#nutC', '#nutF'].forEach(sel => {
    const el = $(sel);
    if (!el) return;
    const key = sel === '#nutP' ? 'p' : sel === '#nutC' ? 'c' : 'f';
    el.oninput = () => { nutDirty[key] = true; paintNutPreview(); };
  });
  // 顶部「食物名」：边输入边给候选，点一下就带出这一份的营养
  const nq = $('#nutNameQ'), sug = $('#nutSug');
  if (nq && sug) {
    let t = null;
    nq.oninput = () => {
      clearTimeout(t);
      t = setTimeout(() => {
        const list = nutFindFoods(nq.value);
        if (!list.length) { sug.hidden = true; sug.innerHTML = ''; return; }
        sug.innerHTML = list.map((f, i) =>
          `<button data-food="${i}">${esc(f.name)} · ${f.kcal} 千卡/100g</button>`).join('');
        sug.hidden = false;
        $$('[data-food]', sug).forEach(b => b.onclick = ev => { ev.preventDefault(); applyNutFood(list[Number(b.dataset.food)]); });
      }, 140);
    };
  }
  $('#nutSave').onclick = saveNutEdit;
  // 记录区里点「继续选」→ 回到搜索，列表放出来，可以接着多选（不跳走）
  const rm = $('#resultMore');
  if (rm) rm.onclick = () => {
    setAddMode('search');
    $('#searchList').hidden = false;
    runSearch($('#searchInput').value || '');
    setTimeout(() => { const b = document.querySelector('#addSheet .sh-body'); if (b) b.scrollTop = 0; }, 30);
  };
  $('#resultReset').onclick = () => {
    S.items = [];
    resetPhotoUI();
    clearDraft();
    $('#resultArea').hidden = true;
    $('#addFoot').hidden = true;
    // 点了「重来」要把搜索列表放出来并重新渲染，否则回到搜索是一页空白
    syncSearchList();
    runSearch($('#searchInput').value || '');
  };

  let searchTimer = null;
  $('#searchInput').oninput = e => {
    clearTimeout(searchTimer);
    const v = e.target.value;
    searchTimer = setTimeout(() => runSearch(v), 120);
  };

  $$('#mealPick .chip').forEach(c => c.onclick = () => {
    S.meal = c.dataset.meal;
    renderMealPick();
  });

  const gm = $('#goMe');
  if (gm) gm.onclick = () => {
    // 已经在设置里、且停在某个子页（身体数据 / 饮食目标 …）→ 先退回设置首页
    if (S.view === 'me' && mePage) { mePage = null; renderMe(); return; }
    switchView(S.view === 'me' ? 'today' : 'me');
  };
  const refreshBtn = $('#cloudRefresh');
  // 手动刷新时，如果还是旧数据，后台再自动补拉几次（GitHub Pages 发布要几十秒）
  let retryLeft = 0, retryBusy = false;
  async function retryPullCloud() {
    if (retryBusy || retryLeft <= 0) return;
    retryBusy = true;
    retryLeft--;
    setTimeout(async () => {
      const d = await pullCloudData();
      if (d) {
        retryLeft = 0; retryBusy = false;
        loadDay();
        updToast('热量数据', lastCloud.at, WATCH_NAME, 3000);
      } else if (retryLeft <= 0) {
        retryBusy = false;
      } else {
        retryPullCloud();
      }
    }, 20000);
  }

  async function pullNow() {
    if (!refreshBtn) return;
    refreshBtn.classList.add('spin');
    let date = null;
    try { date = await pullCloudData(true); } catch (e) {}
    refreshBtn.classList.remove('spin');
    try { await giteeGetText('body.json', true); await giteeGetText('health.json', true); } catch (e) {}
    const gotBody = await pullBodyJson(true);   // 体脂秤那份也一起拉（强制读源）
    loadDay();
    const dd = Store.load().daily[S.today] || {};
    const c = lastCloud;
    if (date) {
      retryLeft = 0;
      if (!runNotifyChecks()) {
        let msg = `✅ 已更新：热量数据 ${c.at.slice(5)} · ${WATCH_NAME}`;
        if (gotBody) msg += `  ｜  体重数据 ${gotBody._at || String(gotBody.d || c.at).slice(5)} · ${SCALE_NAME}`;
        toast(msg, 3200, msg.replace(/ · /g, '\n').replace(/\n\n/g, '\n'));
      }
    }
    else if (c && c.at) {
      retryLeft = 3;
      retryPullCloud();
      toast(`✅ 现在是 ${c.at.slice(5)} 那份（活动 ${c.active} 千卡），后台帮你再等新数据`, 3200);
    }
    else if (dd.active) toast('✅ 已更新：热量数据 · 本地记录', 2400);
    else toast('云端还没有今天的数据，先跑一次「热量采集」', 3000);
  }
  if (refreshBtn) refreshBtn.onclick = () => pullNow();

  $('#weightClose').onclick = closeWeight;
  $('#weightMask').onclick = closeWeight;
  $('#weightSave').onclick = saveWeight;

  $('#helpClose').onclick = closeHelp;
  $('#helpMask').onclick = closeHelp;
  $('#grpClose').onclick = closeGroup;
  $('#grpMask').onclick = closeGroup;
  $('#grpRename').onclick = renameGroup;

  $$('#trendSeg button').forEach(b => b.onclick = () => {
    $$('#trendSeg button').forEach(x => x.classList.toggle('on', x === b));
    S.trendDays = Number(b.dataset.d);
    loadTrends();
  });

  // Safari 里打开的是独立副本，提醒一下，避免和主屏幕 App 的数字混淆
  const standalone = window.navigator.standalone === true ||
    window.matchMedia('(display-mode: standalone)').matches;
  if (!standalone) {
    const b = document.createElement('div');
    b.className = 'safariwarn';
    b.textContent = '你正在 Safari 里打开，这份数据是独立的副本，和主屏幕「热量账本」App 不互通。日常请在主屏幕打开。';
    document.querySelector('.app').prepend(b);
  }

  // 有弹层/卡片打开时锁住背后的页面滚动
  const syncLock = () => {
    const on = !!document.querySelector('.sheet.on, .modal.on');
    document.documentElement.classList.toggle('lock', on);
  };
  new MutationObserver(syncLock).observe(document.body, {
    attributes: true, subtree: true, attributeFilter: ['class'],
  });
  syncLock();

  // 注意：不要给顶栏加 transform 做「补偿」。
  // 之前这里用 offsetTop + scrollY 去位移顶栏，键盘弹起后每点一个更靠下的输入框就多叠一次，
  // 表现就是标题栏越来越往下、和内容之间的缺口越来越大。顶栏现在用 sticky，交给浏览器处理。

  // 手写滚动：不交给系统，顶栏绝对不会跟着动
  // 顶部导航固定 + 内容用「容器原生滚动」：
  // 之前手写 transform 滚动会让 iOS 不知道输入框的真实位置，聚焦时整页乱跳、顶栏跑到中间。
  // 现在滚动全部在 #scroller 这一层（文档本身不滚）：只有容器滚动才能被 overscroll-behavior 关掉
  // 「滑到底还继续拉、拽出一片空白再弹回」这个 iOS 文档级橡皮筋。
  const SC = { el: null, body: null };
  const scEl = () => SC.el || document.getElementById('scroller');
  const scY = () => { const el = scEl(); return el ? el.scrollTop : 0; };
  const scMax = () => { const el = scEl(); return el ? Math.max(0, el.scrollHeight - el.clientHeight) : 0; };
  const scTo = (y) => { const el = scEl(); if (el) el.scrollTop = Math.max(0, Math.round(y)); };
  window.scTop = () => scTo(0);
  window.scMeasure = () => {};
  const initScroll = () => {
    SC.el = document.getElementById('scroller');
    SC.body = document.getElementById('scBody');
    if (!SC.el || !SC.body) return;
    // 键盘弹起时：底部导航和加号直接收起来（否则 iOS 会把它顶到键盘上方浮动），
    // 顶栏用 sticky 交给浏览器钉住，不做任何 transform 位移。
    const activeInput = () => {
      const el = document.activeElement;
      return el && /^(INPUT|TEXTAREA)$/.test(el.tagName) ? el : null;
    };

    // 键盘没弹时的基础底部留白（收键盘时要把"键盘多出来的那截"还回去）
    const basePad = (() => {
      const p = parseFloat(getComputedStyle(SC.body).paddingBottom);
      return isFinite(p) && p > 0 ? p : 118;
    })();

    // ── 键盘态：一套定位公式 + 一套收键盘动画 ────────────────────────────────────
    // 定位：被点的输入框落在「顶栏下沿 ~ 键盘上沿」的正中间。
    // 留白：正好等于「键盘盖住的高度 + 6px」→ 内容末尾最多贴到键盘上沿，滑不出一大片空白。
    // 收键盘：把多出来的留白用 300ms 匀掉，卡片跟着键盘一起平滑落下（不再一下子掉下来）。
    const KB_GAP = 6;
    let kbH = parseFloat(localStorage.getItem('kb_h'));
    // 只认"看着像键盘"的值：太小是动画中间态、太大是历史脏数据，都丢掉重新学
    const saneKbH = (v) => isFinite(v) && v > window.innerHeight * 0.22 && v < window.innerHeight * 0.62;
    if (!saneKbH(kbH)) kbH = Math.round(window.innerHeight * 0.49);
    let fullH = window.innerHeight;   // 没有键盘时的可视高
    let kbB = 0;                      // 键盘态：可见区域底边（屏幕坐标）
    let kbSeen = false;               // 见过键盘真的弹起来
    let kbHomeY = -1;                 // 弹键盘之前的滚动位置（收键盘时平滑落回这里）
    let closeRaf = 0;                 // 收键盘动画句柄
    let fillRaf = 0, fillTarget = null; // 点输入框后的定位（合并成每帧最多一次）
    let fromTap = false;               // 这一次定位是「真点」排的，还是延时兜底排的
    let wantFocus = null, wantUntil = 0; // 「这一下点的是谁」——防系统把焦点挪到别的输入框

    const isKb = () => document.documentElement.classList.contains('kb');
    // 滚动容器的顶边（正常是 0；Safari 里顶上有一条提示条时会往下挪），
    // 位置换算都相对它，避免容器不在 0 时算偏
    const scTopY = () => SC.el.getBoundingClientRect().top;
    const contentEndDoc = () => {
      const pad = parseFloat(getComputedStyle(SC.body).paddingBottom) || 0;
      return SC.body.getBoundingClientRect().bottom - scTopY() + scY() - pad;
    };
    const visibleBottom = () => {
      const vv = window.visualViewport;
      const v = vv ? Math.min(window.innerHeight, vv.height) : window.innerHeight - kbH;
      return Math.round(v);
    };
    // 留白只由「记住的键盘高」决定：pad = 键盘高 + 6。
    // 绝不拿视觉视口（visualViewport）去反推 —— Safari 的地址栏/工具栏一收一展，
    // innerHeight 和 vv 都会变，拿它算留白就会出现「空白忽大忽小、背景飘忽不定」。
    // 这样不管 innerHeight 怎么变，「内容末尾 ~ 键盘上沿」的间隙都是恒定的 6px。
    const shrunkLayout = () => window.innerHeight < fullH - 80;   // 键盘把页面整体顶矮（不是盖在上面）
    const kbPadVal = () => (shrunkLayout() ? KB_GAP : Math.max(KB_GAP, Math.round(kbH + KB_GAP)));
    const kbBottomY = () => (shrunkLayout() ? window.innerHeight : Math.round(window.innerHeight - kbH));
    // 内容末尾（文档坐标）只在进键盘态 / 键盘停稳时量一次，滚动过程中不再触发排版计算
    let kbEndCache = 0;
    // 键盘态能滑到的最远处（用缓存，不碰 DOM）
    const kbMaxY = () => (kbB && kbEndCache ? Math.max(0, scTopY() + kbEndCache - kbB + KB_GAP) : Infinity);
    const kbWantY = () => {
      const tb = document.querySelector('.topbar');
      const tbB = tb ? tb.getBoundingClientRect().bottom : 51;
      const bottom = Math.max(tbB + 140, kbB || (window.innerHeight - kbH));
      return tbB + (bottom - tbB) * 0.5;
    };
    // 留白只在数值真的变了才写：每点一下输入框都写一遍 --kb-pad，整页就要重新排版一次，
    // 连点几下就会明显发卡
    let kbPadNow = -1;
    const setKbPad = (v) => {
      if (Math.round(v) === kbPadNow) return;
      kbPadNow = Math.round(v);
      document.documentElement.style.setProperty('--kb-pad', kbPadNow + 'px');
    };
    const endKb = () => {
      cancelAnimationFrame(closeRaf); closeRaf = 0;
      cancelAnimationFrame(fillRaf); fillRaf = 0; fillTarget = null;
      document.documentElement.classList.remove('kb');
      document.documentElement.style.removeProperty('--kb-pad');
      kbPadNow = -1;
      wantFocus = null;
      kbB = 0; kbSeen = false; kbHomeY = -1; kbEndCache = 0;
    };
    const closeKb = () => {
      if (!isKb() || closeRaf) return;
      cancelAnimationFrame(fillRaf); fillRaf = 0; fillTarget = null;
      const y0 = scY();
      const padKb = parseFloat(getComputedStyle(SC.body).paddingBottom) || 0;
      const extra = Math.max(0, padKb - basePad);
      const maxAfter = Math.max(0, scTopY() + contentEndDoc() + basePad - window.innerHeight);
      // 优先落回"弹键盘之前的位置"（卡片原样落回去）；取不到就按留白差值退回去
      const target = kbHomeY >= 0 ? kbHomeY : Math.max(0, y0 - extra);
      const y1 = Math.max(0, Math.min(target, maxAfter));
      if (Math.abs(y1 - y0) < 2) { endKb(); return; }
      const t0 = performance.now(), dur = 340;
      const step = (now) => {
        const p = Math.min(1, (now - t0) / dur);
        const e = 1 - Math.pow(1 - p, 3);
        scTo(y0 + (y1 - y0) * e);
        if (p < 1) closeRaf = requestAnimationFrame(step);
        else { closeRaf = 0; endKb(); }
      };
      closeRaf = requestAnimationFrame(step);
    };
    // 点输入框只"记一下"，真正滚动放到下一帧再做：
    // 如果 touchend 里立刻滚，iOS 会把这一下点击算到「滚动后挪到手指底下的那一栏」——
    // 表现就是点碳水/蛋白质，光标却跑到脂肪。合并成「一帧一次、以最后一次点击为准」，连点也不抖。
    const applyFill = () => {
      fillRaf = 0;
      const t = fillTarget; fillTarget = null;
      if (!t || !isKb()) return;
      // 手指还按着就不动（延时兜底那一次会被这条挡住）；真点排的那一次不受影响，它在抬手之后才跑
      if (touching && !fromTap) return;
      const r = t.getBoundingClientRect();
      const centerVp = r.top + r.height / 2;                                 // 输入框中心（视口坐标）
      const y = Math.max(0, Math.min(Math.round(scY() + centerVp - kbWantY()), kbMaxY()));
      if (Math.abs(scY() - y) >= 8) scTo(y);        // 已经差不多在中间就不动，免得连点微抖
    };
    const kbFill = (t, tap) => {
      if (!t) return;
      fromTap = !!tap;
      cancelAnimationFrame(closeRaf); closeRaf = 0;
      // 已经在键盘态里（多点几下就是这种情况）就不要再量一遍排版：
      // 每次点都量「内容末尾」会强制重新排版一次，连点几下就发卡
      if (!isKb() || !kbB) {
        if (!isKb()) kbHomeY = scY();    // 记下弹键盘前的位置
        kbB = kbBottomY();                                                     // 键盘弹起后的可见底边
        document.documentElement.classList.add('kb');
        kbEndCache = contentEndDoc();                                          // 只量这一次
        setKbPad(kbPadVal());
      }
      fillTarget = t;
      if (!fillRaf) fillRaf = requestAnimationFrame(applyFill);
    };

    // 排查用：连点版本号 5 次的面板会读这些数字
    window.__taps = window.__taps || [];
    window.__kbd = () => {
      const vv = window.visualViewport;
      const pad = parseFloat(getComputedStyle(SC.body).paddingBottom) || 0;
      const endVp = SC.body.getBoundingClientRect().bottom - pad;
      return {
        kb: isKb() ? 1 : 0, seen: kbSeen ? 1 : 0,
        innerH: Math.round(window.innerHeight), vvH: Math.round(vv ? vv.height : 0), vvTop: Math.round(vv ? vv.offsetTop : 0),
        kbH: Math.round(kbH), kbB: Math.round(kbB), pad: Math.round(pad), base: Math.round(basePad),
        y: Math.round(scY()), max: Math.round(scMax()),
        end: Math.round(endVp), gap: Math.round(kbB ? endVp - kbB : 0), home: kbHomeY,
        taps: window.__taps.slice(-3).join(' · '),
      };
    };

    // 越界回弹：每帧最多检查一次（rAF 合并）。
    // 手指按着的时候一律不动手 —— 键盘态以前每帧 scrollTo 去"拉回边界"，
    // 和系统自己的橡皮筋回弹来回抢，表现就是卡片短短短地抖。
    let clampRaf = 0, touching = false;
    const clamp = () => {
      if (clampRaf || touching) return;
      clampRaf = requestAnimationFrame(() => {
        clampRaf = 0;
        if (touching) return;
        const max = scMax();
        const y = scY();
        if (y < 0) scTo(0);
        else if (y > max + 2) scTo(max);
      });
    };
    SC.el.addEventListener('scroll', clamp, { passive: true });
    const endTouch = () => {
      touching = false;
      setTimeout(() => { if (!touching) clamp(); }, 260);   // 等系统回弹走完再收一次尾
    };
    window.addEventListener('touchstart', () => { touching = true; }, { passive: true });
    window.addEventListener('touchend', endTouch, { passive: true });
    window.addEventListener('touchcancel', endTouch, { passive: true });

    // 键盘态滑到头就别让它继续拽：iOS 的橡皮筋会把内容拽出一大片空白再弹回来，
    // 这一下 Web 层关不掉，只能在「已经到底还要继续拉」的时候把这段手势直接吃掉 —— 硬停。
    let edgeStartY = 0, edgeDir = 0;
    window.addEventListener('touchstart', (e) => {
      if (!isKb()) { edgeDir = 0; return; }
      const t = e.touches && e.touches[0];
      if (!t) return;
      edgeStartY = t.clientY;
      const max = scMax();
      const y = scY();
      edgeDir = y <= 1 ? 1 : (y >= max - 1 ? 2 : 0);   // 1=已经在最顶 2=已经在最底
    }, { passive: true });
    window.addEventListener('touchmove', (e) => {
      if (!isKb()) return;
      const t = e.touches && e.touches[0];
      if (!t) return;
      const dy = edgeStartY - t.clientY;               // >0 = 手指往上划（想往下看）
      const max = scMax();
      const y = scY();
      if ((dy > 0 && y >= max - 1) || (dy < 0 && y <= 1)) e.preventDefault();
    }, { passive: false });

    // 键盘弹起/收起时校准：高度只认"停稳后"的值；收起时用动画把多出来的留白还回去
    if (window.visualViewport) {
      let settle = 0;
      window.visualViewport.addEventListener('resize', () => {
        const vb = visibleBottom();
        if (!isKb()) {
          if (!activeInput()) fullH = window.innerHeight;
          return;
        }
        if (vb < fullH - 80) {                       // 键盘真的弹起来了
          kbSeen = true;
          clearTimeout(settle);
          settle = setTimeout(() => {
            const covered = window.innerHeight - vb > 80 ? window.innerHeight - vb : fullH - vb;
            if (covered > 80 && saneKbH(covered)) {  // 只记"停稳后"的真实键盘高，动画中间态不记
              kbH = Math.round(covered);
              localStorage.setItem('kb_h', String(kbH));
            }
            kbB = kbBottomY();
            kbEndCache = contentEndDoc();
            setKbPad(kbPadVal());
            const t = activeInput();
            if (!t) return;
            const r = t.getBoundingClientRect();
            if (Math.abs(r.top + r.height / 2 - kbWantY()) > 40) kbFill(t);   // 偏了才补，避免二次跳
          }, 240);
        } else if (kbSeen) {                          // 键盘收起了 → 卡片平滑落下
          fullH = window.innerHeight;
          closeKb();
        }
      });
    }

    // 只在"真点"时预先定位（手指滑过输入框不算），键盘弹起前就位 → 之后系统无位移可做
    // 焦点也在这里自己定：iOS 那一下"点击"是抬手之后才派发的，页面只要在这中间挪过，
    // 它就会重新挑一次元素，落到"挪完之后手指底下"的那一栏 —— 表现就是点碳水、光标跳到脂肪。
    // 所以：先把自己要的那一栏聚焦，再把这一下合成的点击吃掉，最后才挪页面。
    let tX = 0, tY = 0, tT = 0, tEl = null;
    SC.el.addEventListener('touchstart', e => {
      const t = e.touches[0];
      tX = t.clientX; tY = t.clientY; tT = Date.now();
      tEl = e.target.closest ? e.target.closest('input,textarea') : null;
      wantFocus = null;                    // 新手势开始，上一轮的防线作废
    }, { passive: true });
    SC.el.addEventListener('touchend', e => {
      if (!tEl) return;
      const c = e.changedTouches[0];
      const moved = Math.abs(c.clientY - tY) + Math.abs(c.clientX - tX);
      const dur = Date.now() - tT;
      if (moved < 8 && dur < 400) {
        const el = tEl;
        try { el.focus({ preventScroll: true }); } catch (_) { try { el.focus(); } catch (_) {} }
        // 焦点已经落在你点的那一栏了 → 这一下点击不需要再"选一次"，吃掉它
        // （第一次点、键盘还没弹起时不拦：那一下交给系统自己走，保证键盘一定能出来）
        if (document.activeElement === el && isKb()) e.preventDefault();
        // 布防要在自己 focus 之后：否则刚才那次 focusin 会立刻把防线撤掉
        wantFocus = el; wantUntil = Date.now() + 600;   // 只需要覆盖「抬手→点击派发」这一小段
        if (window.__taps) window.__taps.push((el.id || el.tagName) + '→' + ((document.activeElement && (document.activeElement.id || document.activeElement.tagName)) || '?'));
        kbFill(el, true);
      }
      tEl = null;
    }, { passive: false });

    // 兜底：万一系统还是把焦点挪到了别的输入框（上面那下点击没吃掉），拨回你真正点的那一栏
    SC.el.addEventListener('focusin', e => {
      const want = wantFocus;
      if (!want || Date.now() > wantUntil) return;
      const t = e.target;
      if (t === want) { wantFocus = null; return; }
      if (!t || !/^(INPUT|TEXTAREA)$/.test(t.tagName)) return;
      wantFocus = null;
      if (window.__taps) window.__taps.push('修正:' + (want.id || want.tagName) + '夺回');
      try { want.focus({ preventScroll: true }); } catch (_) { try { want.focus(); } catch (_) {} }
      kbFill(want);
    }, true);

    // 兜底：用键盘上的「上一项 / 下一项」切焦点时没有真点；等键盘稳了按同一条公式再对一次
    SC.el.addEventListener('focusin', e => {
      const t = e.target;
      if (!t || !/^(INPUT|TEXTAREA)$/.test(t.tagName)) return;
      document.documentElement.classList.add('kb');
      setTimeout(() => {
        if (activeInput() !== t) return;
        const r = t.getBoundingClientRect();
        const off = Math.abs(r.top + r.height / 2 - kbWantY());
        if (off > 40) kbFill(t);     // 已经在中间附近就不动，避免二次跳
      }, 380);
    });

    document.addEventListener('focusout', () => {
      setTimeout(() => {
        if (activeInput()) return;
        if (isKb()) closeKb();     // 收键盘走动画（等 700ms 是防"点了别的输入框却瞬时失焦"）
        else endKb();
      }, 700);
    });
  };

  // 左边缘拖动返回：卡片跟手滑动，松手决定回退还是弹回
  let sw = null;
  document.addEventListener('touchstart', e => {
    const t = e.touches[0];
    if (t.clientX > 30) { sw = null; return; }
    const el = document.querySelector('.sheet.on') || document.querySelector('.modal.on');
    sw = el
      ? { el, x0: t.clientX, y0: t.clientY, dx: 0, active: false }
      : { el: null, x0: t.clientX, y0: t.clientY, dx: 0, active: false };
  }, { passive: true });

  document.addEventListener('touchmove', e => {
    if (!sw) return;
    const t = e.touches[0];
    const dx = t.clientX - sw.x0;
    const dy = Math.abs(t.clientY - sw.y0);
    if (!sw.active) {
      if (dx < 8) return;
      if (dy > Math.abs(dx)) { sw = null; return; }   // 竖着滑，交给页面滚动
      sw.active = true;
      if (sw.el) sw.el.classList.add('dragging');
    }
    sw.dx = Math.max(0, dx);
    if (sw.el) {
      sw.el.style.transform = 'translateX(' + sw.dx + 'px)';
      sw.el.style.opacity = String(Math.max(0.55, 1 - sw.dx / 700));
    }
  }, { passive: true });

  document.addEventListener('touchend', () => {
    if (!sw) return;
    const { el, dx, active } = sw;
    sw = null;
    if (!active) return;
    if (el) el.classList.remove('dragging');
    if (dx > 100) {
      if (el) {
        el.style.transition = 'transform .3s cubic-bezier(.32,.72,0,1), opacity .3s ease-out';
        el.style.transform = 'translateX(102%)';
        el.style.opacity = '0';
      }
      setTimeout(() => {
        if (el) { el.style.transition = ''; el.style.transform = ''; el.style.opacity = ''; }
        goBack();
      }, 270);
    } else if (el) {
      el.style.transition = 'transform .38s cubic-bezier(.32,.72,0,1), opacity .32s ease-out';
      el.style.transform = '';
      el.style.opacity = '';
      setTimeout(() => { el.style.transition = ''; }, 400);
    } else {
      goBack();
    }
  }, { passive: true });

  // Dock 的圆角：跟这台设备自己的屏幕圆角"同心"（屏幕圆角半径 − Dock 离屏幕边的距离）。
  // 各代 iPhone 的屏幕圆角本来就不一样，iPad 的又比手机紧得多，所以按屏宽取一档，不写死一个值。
  const SCREEN_R = [[320, 0], [375, 44], [390, 47], [393, 55], [402, 55], [414, 49], [428, 53], [430, 55], [440, 62], [460, 66]];
  // 自查面板里手动调过的三个值（圆角 / 高度 / 离底）优先，调好会记住
  const applyDockTune = () => {
    const de = document.documentElement;
    const num = (k, min, max) => {
      const v = parseFloat(localStorage.getItem(k) || '');
      if (!(v >= min && v <= max)) return null;
      return Math.round(v);
    };
    const h = num('dock_h', 64, 140), b = num('dock_b', 4, 60);
    if (h) de.style.setProperty('--dock-h', h + 'px');
    if (b) de.style.setProperty('--dock-bottom', b + 'px');
  };
  const syncDockR = () => {
    const ov = parseFloat(localStorage.getItem('dock_r') || '');
    if (ov >= 8 && ov <= 60) {                 // 自查面板里手动调过的值优先
      document.documentElement.style.setProperty('--dock-r', Math.round(ov) + 'px');
      return;
    }
    const w = Math.round(window.innerWidth);
    const pad = window.matchMedia('(min-width: 700px)').matches;
    // 两边的边距、高度都以 CSS 里那份为准，避免脚本和样式各写一个值
    const cs = getComputedStyle(document.documentElement);
    const inset = parseFloat(cs.getPropertyValue('--dock-inset')) || 14;
    const h = parseFloat(cs.getPropertyValue('--dock-h')) || (pad ? 96 : 88);
    let r;
    if (pad) {
      // iPad 的屏幕圆角比 iPhone 紧得多（约 34），Dock 不能照抄手机的「高度一半」
      r = Math.max(18, Math.min(34 - inset, h * 0.34));
    } else {
      let sr = 0;
      for (const [ww, srr] of SCREEN_R) { if (w >= ww) sr = srr; }
      r = Math.max(14, Math.min(sr - inset, h / 2));   // 手机：给到高度的一半，最贴近屏幕弧
    }
    document.documentElement.style.setProperty('--dock-r', Math.round(r) + 'px');
  };

  // 顶栏改成 fixed：量出实际高度，给内容让出空间
  const syncTopH = () => {
    const tb = document.querySelector('.topbar');
    if (tb) document.documentElement.style.setProperty('--topbar-h', Math.round(tb.getBoundingClientRect().height) + 'px');
  };
  // 启动时把顶栏重绘一次：iOS 主屏幕 App 刚打开时会在状态栏区域压一层半透明底，
  // 重新合成这一层可以让它立刻消失，而不是要等一会儿
  const clearScrim = () => {
    const tb = document.querySelector('.topbar');
    if (!tb) return;
    tb.style.transform = 'translateZ(0)';
    requestAnimationFrame(() => requestAnimationFrame(() => { tb.style.transform = ''; }));
  };
  setTimeout(clearScrim, 60);
  setTimeout(clearScrim, 600);
  setTimeout(clearScrim, 1600);
  window.addEventListener('pageshow', () => setTimeout(clearScrim, 80));
  document.addEventListener('visibilitychange', () => { if (!document.hidden) setTimeout(clearScrim, 80); });

  const bt = $('#brandTag');
  if (bt) {
    bt.textContent = APP_VERSION;
    // 排查用：连点版本号 5 次，显示当前环境信息（再点一次关闭）
    let taps = 0, tapT = 0;
    bt.addEventListener('click', () => {
      const now = Date.now();
      taps = (now - tapT < 900) ? taps + 1 : 1;
      tapT = now;
      if (taps < 5) return;
      taps = 0;
      const vv = window.visualViewport;
      const box = document.createElement('div');
      box.style.cssText = 'position:fixed;left:8px;right:8px;bottom:96px;z-index:9999;background:#000;color:#7dff8a;font:12px/1.5 ui-monospace,Menlo,monospace;padding:10px 12px;border-radius:10px;white-space:pre-wrap;border:1px solid #2c5';
      const rows = () => {
        const k = (window.__kbd && window.__kbd()) || {};
        return [
          '版本 ' + APP_VERSION + (window.navigator.standalone === true ? ' 独立' : ' 浏览器'),
          '键盘态 ' + (k.kb || 0) + ' 见过 ' + (k.seen || 0) + ' 键盘高记忆 ' + (k.kbH || 0),
          'innerH ' + (k.innerH || 0) + ' vvH ' + (k.vvH || 0) + ' vvTop ' + (k.vvTop || 0),
          '可见底边 ' + (k.kbB || 0) + ' 留白 ' + (k.pad || 0) + '(基础 ' + (k.base || 0) + ')',
          '滚动 ' + (k.y || 0) + ' / 上限 ' + (k.max || 0),
          '内容末尾 ' + (k.end || 0) + ' 间隙 ' + (k.gap || 0) + ' 回位 ' + (k.home === undefined ? '-' : k.home),
          '点击 ' + (k.taps || '-'),
        ].join('\n');
      };
      box.onclick = () => box.remove();
      const textEl = document.createElement('div');
      textEl.style.cssText = 'white-space:pre-wrap';
      textEl.textContent = rows();
      box.appendChild(textEl);

      // Dock 现场微调：圆角 / 高度 / 离底 —— 在真机上一边看一边调，不用来回发版
      const de = document.documentElement;
      const cur = (k, dflt) => {
        const v = parseFloat(getComputedStyle(de).getPropertyValue(k));
        return Math.round(isFinite(v) && v > 0 ? v : dflt);
      };
      const bar = document.createElement('div');
      bar.style.cssText = 'display:flex;flex-direction:column;gap:7px;margin-top:9px';
      const mkBtn = (label, fn) => {
        const b = document.createElement('button');
        b.textContent = label;
        b.style.cssText = 'flex:1;padding:8px 0;border-radius:9px;background:#0e2116;color:#7dff8a;border:1px solid #2c5;font:12px ui-monospace,Menlo,monospace';
        b.onclick = (ev) => { ev.stopPropagation(); fn(); };
        return b;
      };
      const row = (name, key, cssVar, min, max, step, after) => {
        const r = document.createElement('div');
        r.style.cssText = 'display:flex;gap:7px;align-items:center';
        const v = document.createElement('span');
        v.style.cssText = 'min-width:74px;text-align:center;color:#d6ff4b;font-weight:700;font-size:11px';
        const show = () => { v.textContent = name + ' ' + cur(cssVar, min); };
        const set = (val) => {
          val = Math.max(min, Math.min(max, Math.round(val)));
          de.style.setProperty(cssVar, val + 'px');
          localStorage.setItem(key, String(val));
          if (after) after();
          show();
        };
        show();
        r.append(mkBtn('−', () => set(cur(cssVar, min) - step)), v, mkBtn('＋', () => set(cur(cssVar, min) + step)));
        return r;
      };
      bar.append(row('圆角', 'dock_r', '--dock-r', 8, 60, 4));
      bar.append(row('高度', 'dock_h', '--dock-h', 64, 140, 4));
      bar.append(row('离底', 'dock_b', '--dock-bottom', 4, 48, 4));
      box.appendChild(bar);
      document.body.appendChild(box);
      // 边滑边更新，方便一次截图看清
      const tick = setInterval(() => {
        if (!box.isConnected) { clearInterval(tick); return; }
        textEl.textContent = rows();
      }, 200);
    });
  }
  syncTopH();
  applyDockTune();
  syncDockR();
  initScroll();
  const relayout = () => {
    syncTopH();
    syncDockR();
    // 横竖屏切换后「关于」页的铺满高度要重算，否则会照搬竖屏的高度
    if (typeof fitAboutFill === 'function') fitAboutFill();
  };
  window.addEventListener('resize', relayout);
  window.addEventListener('orientationchange', relayout);

  // 版本自检：线上版本变了就带随机参数重开，绕开缓存
  const checkVersion = async () => {
    try {
      const r = await fetchT('version.txt?t=' + Date.now(), { cache: 'no-store' }, 4000);
      if (!r.ok) return;
      const v = (await r.text()).trim();
      // 以前用"本次会话只跳一次"的标记：PWA 挂在后台好几天，
      // 那个标记一直留着，就再也不自动更新了（表现为版本号卡在旧版）。
      // 改成"15 秒内不重复跳"，每次发现新版本都会自己更新。
      const lastJump = Number(sessionStorage.getItem('ver-jump-at') || 0);
      if (v && v !== APP_VERSION && Date.now() - lastJump > 15000) {
        sessionStorage.setItem('ver-jump-at', String(Date.now()));
        sessionStorage.removeItem('ver-jump');
        location.replace(location.pathname + '?r=' + Date.now());
      }
    } catch (e) { /* 没网就算了 */ }
  };
  checkVersion();
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') checkVersion();
  });

  applyTheme(Store.load().settings.theme || 'lime');

  // 有 token 的话，先拉云端：比本地新就覆盖，然后刷新界面
  if (typeof cloudToken === 'function' && cloudToken()) {
    cloudPull().then(r => {
      if (r === 'pulled') {
        applyTheme(Store.load().settings.theme || 'lime');
        loadDay();
        if (S.view === 'me') renderMe();
        toast('☁️ 已从云端恢复最新数据', 3000);
      }
    });
  }

  refreshPushState().then(() => {
    if (mePage === 'notify') { try { renderMe(); } catch (e) {} }
  }).catch(() => {});

  const bell = $('#notifyBell');
  if (bell) bell.onclick = () => openNotifyLog();
  const nlogClose = $('#nlogClose'), nlogMask = $('#nlogMask'), nlogClear = $('#nlogClear');
  if (nlogClose) nlogClose.onclick = () => closeNotifyLog();
  if (nlogMask) nlogMask.onclick = () => closeNotifyLog();
  if (nlogClear) nlogClear.onclick = () => {
    const d = Store.load(); d.notifyLog = []; Store.save({ silent: true });
    openNotifyLog(); toast('已清空提醒记录', 1600);
  };
  // 一次性清理：迁移到 Gitee 之前留下的旧提醒（文案里还写着 GitHub）
  try {
    if (!localStorage.getItem('notify_purged_v1')) {
      const d = Store.load();
      if (Array.isArray(d.notifyLog)) {
        d.notifyLog = d.notifyLog.filter(x => !/GitHub/i.test(String(x.b || '')));
        Store.save({ silent: true });
      }
      localStorage.setItem('notify_purged_v1', '1');
    }
  } catch (e) {}
  renderNotifyDot();
  wireNotifyDrag();

  const hrTop = $('#hardReloadTop');
  if (hrTop) hrTop.onclick = () => hardReloadApp();

  const bodyDate = consumeBodyLink();
  loadDay();
  // 打开 App 时先拉一次；如果「打开账本自动采集」的快捷指令正在后台写数据，
  // 再补拉两次，保证它写完之后能立刻显示出来
  // 有待上传的改动（上次网络失败）→ 打开就补传一次
  if (cloudToken() && localStorage.getItem('pending_push')) {
    setTimeout(() => { try { cloudPush(); } catch (e) {} }, 2500);
  }
  pullBodyHistory().then(n => { if (n) { try { loadDay(); } catch (e) {} } });
  const grabBody = (retry) => pullBodyJson().then(j => {
    if (j) {
      try { loadDay(); } catch (e) {}
      try { clearErr('err-body'); clearErr('err-history'); } catch (e) {}
      const what = (j.w && j.bf) ? '体重+体脂数据' : (j.bf ? '体脂数据' : '体重数据');
      updToast(what, j.d, SCALE_NAME, 2600);
      try {
        // 从已保存的数据里取（四项都带上）
        const st = Store.load();
        const all = Object.keys(st.body || {}).concat(Object.keys(st.weights || {})).sort();
        const dd = String(j.d || '').slice(0, 10) || all[all.length - 1];
        const b2 = (st.body || {})[dd] || {};
        const w2 = (st.weights || {})[dd];
        const bits = [];
        if (w2) bits.push('体重 ' + w2 + ' kg');
        if (b2.bf) bits.push('体脂 ' + b2.bf + '%');
        if (b2.bmi) bits.push('BMI ' + b2.bmi);
        if (b2.ffm) bits.push('去脂 ' + b2.ffm + ' kg');
        logNotify('body', '体重数据已更新', (bits.length ? bits.join(' · ') : '（四项都为空）') + (j._at ? ' · 采集 ' + j._at : ''));
      } catch (e) {}
    }
    // 只有「还没拿到今天的数据」才补拉，避免每次打开都多打两次网络
    const today = new Date();
    const p2 = n => String(n).padStart(2, '0');
    const ds = today.getFullYear() + '-' + p2(today.getMonth() + 1) + '-' + p2(today.getDate());
    if (retry > 0 && (!j || String(j.d || '').slice(0, 10) !== ds)) {
      setTimeout(() => grabBody(retry - 1), 3000);
    }
  });
  grabBody(2);
  if (synced) {
    setTimeout(() => updToast('热量数据', synced, WATCH_NAME, 3000), 700);
  }
  setTimeout(() => { try { runNotifyChecks(); } catch (e) {} renderNotifyDot(); }, 1200);

  // 打开时拉一次云端数据（不阻塞界面）
  pullCloudData().then(date => {
    if (!date) return;
    loadDay();
    updToast('热量数据', date, WATCH_NAME, 2600);
  });

  // 跨天检测：放在后台过夜，第二天打开要自动切到今天
  const checkDay = () => {
    const t = todayISO();
    if (t === S.today) return;
    S.today = t;
    S.date = t;
    loadDay();
  };
  setTimeout(checkDay, 1500);
  setInterval(checkDay, 30000);
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') checkDay();
  });

  // 从后台切回来：立刻拉一次；没新数据就静默补拉几次（快捷指令刚写完时 Pages 还没发布）
  let lastPull = 0, autoN = 0;
  const autoCatchUp = () => {
    if (autoN >= 4) return;
    autoN++;
    setTimeout(async () => {
      const d = await pullCloudData();
      if (d) {
        autoN = 0;
        loadDay();
        updToast('热量数据', d, WATCH_NAME, 2400);
      } else {
        autoCatchUp();
      }
    }, 20000);
  };
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible') return;
    lastPull = Date.now();
    // 切回前台也刷一次身体数据（历史 + 当天）
    pullBodyHistory().then(n => { if (n) { try { loadDay(); } catch (e) {} } });
    pullBodyJson().then(j => { if (j) { try { loadDay(); } catch (e) {} } });
    if (cloudToken() && localStorage.getItem('pending_push')) { try { cloudPush(); } catch (e) {} }
    pullCloudData().then(date => {
      if (date) { loadDay(); updToast('热量数据', date, WATCH_NAME, 2200); }
      else autoCatchUp();
    });
  });

  // 两台设备互相同步记录：切回前台就拉一次，开着的时候每 90 秒也拉一次
  // （只在开了「自动同步」、两台都填了同一个 Token 时才有东西可拉）
  const syncRecords = () => {
    if (typeof cloudToken !== 'function' || !cloudToken()) return;
    cloudPull().then(r => {
      if (r === 'error' && notifyCfg().fail) { toast('☁️ 同步失败：读不到云端数据', 3600); return; }
      if (r !== 'pulled' && r !== 'merged') return;
      applyTheme(Store.load().settings.theme || 'lime');
      loadDay();
      if (S.view === 'me') renderMe();
      if (S.view === 'trends') loadTrends();
      try { runNotifyChecks(); } catch (e) {}
    }).catch(() => {});
  };
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') syncRecords();
  });
  setInterval(() => { if (!document.hidden) syncRecords(); }, 30000);
}

document.addEventListener('DOMContentLoaded', init);
